const TWIPS_PER_CSS_PIXEL: f32 = 15.0;
const EMU_PER_CSS_PIXEL: f32 = 9_525.0;
const POINTS_TO_CSS_PIXELS: f32 = 96.0 / 72.0;
const DOCX_BORDER_GRID_CSS_PIXELS: f32 = 0.96;
const DEFAULT_PAGE_WIDTH_TWIPS: u32 = 12_240;
const DEFAULT_PAGE_HEIGHT_TWIPS: u32 = 15_840;
const DEFAULT_MARGIN_TWIPS: u32 = 1_440;
const DEFAULT_HEADER_FOOTER_DISTANCE_TWIPS: u32 = 720;
// Word uses 10pt when no run, style, or document default supplies a size.
const DEFAULT_FONT_SIZE: f32 = 10.0 * POINTS_TO_CSS_PIXELS;
const DEFAULT_PARAGRAPH_AFTER: f32 = 0.0;
// Canvas font boxes omit the external leading Word includes in natural spacing.
// Keep measured metrics above Word's minimum; retain the fallback for v1 tables.
const BODY_FONT_LINE_BOX_EM: f32 = 1.31;
const WORD_MINIMUM_NATURAL_LINE_BOX_EM: f32 = 1.15;
const WORD_DEFAULT_LINE_BOX_EM: f32 = 1.3;
// Scalar advances cannot preserve shaping across fallback-script run boundaries.
const EAST_ASIAN_AUTO_SPACING_EM: f32 = 0.25;
const CELL_PADDING: f32 = 4.0;
const FOOTNOTE_SEPARATOR_AREA_HEIGHT: f32 = 12.0;
const MAX_PAGE_COUNT: usize = 10_000;
const EQUATION_PLACEHOLDER: char = '\u{2003}';

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum DocxBorderPattern {
    Single,
    SmallGapDash,
    Double,
    ThickThin,
    ThinThick,
    Triple,
    ZigZag,
    Emoji(&'static str),
    Gems,
    WeavingAngles,
    Art,
}

fn compound_border_visual(visual: Visual, compound: LineCompound) -> Visual {
    if compound == LineCompound::Single {
        visual
    } else {
        Visual::StrokeStyle {
            style: StrokeStyle {
                compound,
                ..StrokeStyle::default()
            },
            visual: Box::new(visual),
        }
    }
}

fn table_cell_visual(
    fill: Paint,
    border_color: u32,
    border_width: f32,
    border_compound: LineCompound,
    borders: &CellBorders,
) -> Visual {
    let edges = [borders.top, borders.right, borders.bottom, borders.left];
    let border_width = if borders.suppresses_edge()
        || borders.has_dashes()
        || (edges.iter().any(Option::is_some) && edges.iter().any(Option::is_none))
    {
        0.0
    } else {
        border_width
    };
    let visual = Visual::PaintedShape {
        geometry: Geometry::Rectangle,
        fill,
        stroke: if border_width > 0.0 {
            Paint::Solid(border_color)
        } else {
            Paint::None
        },
        stroke_width: border_width.max(0.0),
    };
    compound_border_visual(visual, border_compound)
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct DocxBorder {
    width: f32,
    stroke_width: f32,
    space: f32,
    color: u32,
    pattern: DocxBorderPattern,
}

impl DocxBorder {
    fn visual(self, geometry: Geometry) -> Visual {
        let visual = Visual::PaintedShape {
            geometry,
            fill: Paint::None,
            stroke: Paint::Solid(self.color),
            stroke_width: self.stroke_width,
        };
        if self.pattern == DocxBorderPattern::SmallGapDash {
            return Visual::StrokeStyle {
                style: StrokeStyle {
                    // Word small-gap borders use four stroke widths on, one off.
                    dash: drawingml_dash_lengths(&[4.0, 1.0], self.stroke_width),
                    ..StrokeStyle::default()
                },
                visual: Box::new(visual),
            };
        }
        let compound = match self.pattern {
            DocxBorderPattern::Single
            | DocxBorderPattern::SmallGapDash
            | DocxBorderPattern::Emoji(_)
            | DocxBorderPattern::Gems
            | DocxBorderPattern::WeavingAngles
            | DocxBorderPattern::Art => {
                return visual;
            }
            DocxBorderPattern::Double => LineCompound::Double,
            DocxBorderPattern::ThickThin => LineCompound::ThickThin,
            DocxBorderPattern::ThinThick => LineCompound::ThinThick,
            DocxBorderPattern::Triple => LineCompound::Triple,
            DocxBorderPattern::ZigZag => LineCompound::Single,
        };
        compound_border_visual(visual, compound)
    }

    fn compound(self) -> LineCompound {
        match self.pattern {
            DocxBorderPattern::Double => LineCompound::Double,
            DocxBorderPattern::ThickThin => LineCompound::ThickThin,
            DocxBorderPattern::ThinThick => LineCompound::ThinThick,
            DocxBorderPattern::Triple => LineCompound::Triple,
            _ => LineCompound::Single,
        }
    }

    fn approximation_message(self) -> Option<&'static str> {
        match self.pattern {
            DocxBorderPattern::Emoji(_) => {
                Some("DOCX cakeSlice art border uses a Unicode emoji approximation")
            }
            DocxBorderPattern::Gems => {
                Some("DOCX gems art border uses a vector approximation of the native artwork")
            }
            DocxBorderPattern::WeavingAngles => Some(
                "DOCX weavingAngles art border uses a vector approximation of the native artwork",
            ),
            DocxBorderPattern::Art => {
                Some("DOCX art border uses a visible solid-line approximation")
            }
            _ => None,
        }
    }
}

fn docx_border_geometry(border: DocxBorder, length: f32, vertical: bool) -> Geometry {
    let height = border.width.max(border.stroke_width);
    let mut commands = match border.pattern {
        DocxBorderPattern::Single
        | DocxBorderPattern::SmallGapDash
        | DocxBorderPattern::Double
        | DocxBorderPattern::ThickThin
        | DocxBorderPattern::ThinThick
        | DocxBorderPattern::Triple
        | DocxBorderPattern::Emoji(_)
        | DocxBorderPattern::Gems
        | DocxBorderPattern::WeavingAngles
        | DocxBorderPattern::Art => vec![
            PathCommand::MoveTo {
                x: 0.0,
                y: height / 2.0,
            },
            PathCommand::LineTo {
                x: length,
                y: height / 2.0,
            },
        ],
        DocxBorderPattern::ZigZag => {
            let step = (height / 2.0).max(border.stroke_width * 2.0);
            let mut commands = vec![PathCommand::MoveTo {
                x: 0.0,
                y: height / 2.0,
            }];
            let mut x = step;
            let mut high = true;
            while x < length && commands.len() < 2_048 {
                commands.push(PathCommand::LineTo {
                    x,
                    y: if high { 0.0 } else { height },
                });
                high = !high;
                x += step;
            }
            commands.push(PathCommand::LineTo {
                x: length,
                y: height / 2.0,
            });
            commands
        }
    };
    if vertical {
        for command in &mut commands {
            match command {
                PathCommand::MoveTo { x, y } | PathCommand::LineTo { x, y } => {
                    std::mem::swap(x, y);
                }
                PathCommand::ClosePath => {}
                _ => unreachable!("page-border geometry uses only line segments"),
            }
        }
    }
    Geometry::Path {
        fill_rule: FillRule::NonZero,
        commands,
    }
}

// Word's gems border is a two-column chain with round end caps. Keep the
// artwork in the DOCX adapter; other formats have no equivalent art-border enum.
fn page_border_gems_visual(border: DocxBorder, bounds: Rect, vertical: bool) -> Visual {
    let thickness = if vertical {
        bounds.width
    } else {
        bounds.height
    };
    let length = if vertical {
        bounds.height
    } else {
        bounds.width
    };
    let count = (length / thickness).floor().clamp(2.0, 512.0) as usize;
    let step = length / count as f32;
    let mut paths = vec![Vec::new(); 4];
    for tile in 0..count {
        let mut polygon = |layer: usize, points: &[(f32, f32)]| {
            let points = points
                .iter()
                .map(|&(x, y)| {
                    let (x, y) = (x * thickness, (tile as f32 + y) * step);
                    if vertical { (x, y) } else { (y, x) }
                })
                .collect::<Vec<_>>();
            if let Geometry::Path { commands, .. } = super::polygon_geometry(&points) {
                paths[layer].extend(commands);
            }
        };
        // Connecting bars are behind the gems, including the round end caps.
        for x in [0.2, 0.8] {
            polygon(
                0,
                &[
                    (x - 0.037, 0.2),
                    (x + 0.037, 0.2),
                    (x + 0.037, 0.8),
                    (x - 0.037, 0.8),
                ],
            );
        }
        for y in [0.2, 0.8] {
            polygon(
                0,
                &[
                    (0.2, y - 0.037),
                    (0.8, y - 0.037),
                    (0.8, y + 0.037),
                    (0.2, y + 0.037),
                ],
            );
        }
        for (column, x) in [0.0, 0.59].into_iter().enumerate() {
            if column == 0 && (tile == 0 || tile + 1 == count) {
                for (layer, radius) in [(0, 0.205), (1, 0.17), (1, 0.15), (1, 0.13)] {
                    // Even-odd fill preserves the concentric rings within each paint layer.
                    let points = (0..32)
                        .map(|i| {
                            let angle = i as f32 * std::f32::consts::TAU / 32.0;
                            (0.205 + radius * angle.cos(), 0.5 + radius * angle.sin())
                        })
                        .collect::<Vec<_>>();
                    polygon(layer, &points);
                }
                let points = (0..=16)
                    .map(|i| {
                        let angle = (i as f32 / 16.0 + 0.25) * std::f32::consts::PI;
                        (0.205 + 0.13 * angle.cos(), 0.5 + 0.13 * angle.sin())
                    })
                    .collect::<Vec<_>>();
                polygon(2, &points);
                continue;
            }
            for (row, y) in [0.0, 0.59].into_iter().enumerate() {
                polygon(
                    0,
                    &[(x, y), (x + 0.41, y), (x + 0.41, y + 0.41), (x, y + 0.41)],
                );
                for inset in [0.04, 0.065, 0.085] {
                    polygon(
                        1,
                        &[
                            (x + inset, y + inset),
                            (x + 0.41 - inset, y + inset),
                            (x + 0.41 - inset, y + 0.41 - inset),
                            (x + inset, y + 0.41 - inset),
                        ],
                    );
                }
                let (left, right, top, bottom) = (x + 0.085, x + 0.325, y + 0.085, y + 0.325);
                let points = if column == row {
                    [(left, top), (right, top), (left, bottom)]
                } else {
                    [(left, top), (right, top), (right, bottom)]
                };
                polygon(2, &points);
                let diagonal = if column == row {
                    [(x + 0.04, y + 0.37), (x + 0.37, y + 0.04)]
                } else {
                    [(x + 0.04, y + 0.04), (x + 0.37, y + 0.37)]
                };
                polygon(3, &diagonal);
            }
        }
    }
    Visual::Group {
        children: paths
            .into_iter()
            .enumerate()
            .map(|(layer, commands)| VisualBrushChild {
                bounds,
                visual: Visual::PaintedShape {
                    geometry: Geometry::Path {
                        fill_rule: if layer == 1 {
                            FillRule::EvenOdd
                        } else {
                            FillRule::NonZero
                        },
                        commands,
                    },
                    fill: match layer {
                        0 => Paint::Solid(border.color),
                        1 => Paint::Solid(0xffff_ffff),
                        2 => Paint::Solid(0xc0c0_c0ff),
                        _ => Paint::None,
                    },
                    stroke: if layer == 3 {
                        Paint::Solid(0xffff_ffff)
                    } else {
                        Paint::None
                    },
                    stroke_width: if layer == 3 { thickness * 0.012 } else { 0.0 },
                },
            })
            .collect(),
    }
}

// This artwork has a tall, spaced repeat and separate corner ornaments;
// it cannot use the square gems repeat without changing the authored pattern.
fn page_border_weaving_angles_visual(border: DocxBorder, bounds: Rect, vertical: bool) -> Visual {
    let thickness = if vertical {
        bounds.width
    } else {
        bounds.height
    };
    let length = if vertical {
        bounds.height
    } else {
        bounds.width
    };
    let cap = thickness.min(length / 2.0);
    let body_length = length - 2.0 * cap;
    let count = (body_length / (thickness * 744.0 / 268.0))
        .floor()
        .clamp(1.0, 512.0) as usize;
    let step = body_length / count as f32;
    let mut paths = vec![Vec::new(); 3];
    for tile in 0..count + 2 {
        let end_cap = tile == 0 || tile == count + 1;
        let (offset, height, units) = if tile == 0 {
            (0.0, cap, 268.0)
        } else if tile == count + 1 {
            (length - cap, cap, 268.0)
        } else {
            (cap + (tile - 1) as f32 * step, step, 744.0)
        };
        let mut path = |layer: usize, points: &[(f32, f32)], closed: bool| {
            let points = points
                .iter()
                .map(|&(x, y)| {
                    let y = if tile == count + 1 { units - y } else { y };
                    let (x, y) = (x / 268.0 * thickness, offset + y / units * height);
                    if vertical { (x, y) } else { (y, x) }
                })
                .collect::<Vec<_>>();
            if let Geometry::Path { mut commands, .. } = super::polygon_geometry(&points) {
                if !closed {
                    commands.pop();
                }
                paths[layer].extend(commands);
            }
        };
        if end_cap {
            path(
                0,
                &[(0.0, 0.0), (268.0, 0.0), (268.0, 268.0), (0.0, 268.0)],
                true,
            );
            path(2, &[(0.0, 268.0), (0.0, 0.0), (258.0, 0.0)], false);
            path(2, &[(32.0, 268.0), (32.0, 32.0), (268.0, 32.0)], false);
            path(1, &[(214.0, 268.0), (268.0, 214.0), (268.0, 268.0)], true);
            for points in [
                [(65.0, 54.0), (136.0, 93.0), (114.0, 102.0), (103.0, 126.0)],
                [(230.0, 54.0), (192.0, 126.0), (181.0, 102.0), (158.0, 93.0)],
                [
                    (65.0, 220.0),
                    (102.0, 143.0),
                    (114.0, 173.0),
                    (136.0, 181.0),
                ],
                [
                    (230.0, 220.0),
                    (158.0, 181.0),
                    (181.0, 173.0),
                    (192.0, 143.0),
                ],
            ] {
                path(1, &points, true);
            }
        } else {
            path(
                0,
                &[(40.0, 113.0), (228.0, 113.0), (228.0, 631.0), (40.0, 631.0)],
                true,
            );
            for points in [
                [(47.0, 113.0), (198.0, 263.0), (198.0, 481.0), (48.0, 631.0)],
                [(77.0, 113.0), (220.0, 256.0), (220.0, 489.0), (78.0, 631.0)],
            ] {
                path(2, &points, false);
            }
            path(
                2,
                &[(40.0, 113.0), (228.0, 113.0), (228.0, 631.0), (40.0, 631.0)],
                true,
            );
            path(
                1,
                &[
                    (182.0, 113.0),
                    (55.0, 241.0),
                    (55.0, 496.0),
                    (190.0, 631.0),
                    (228.0, 631.0),
                    (78.0, 480.0),
                    (78.0, 258.0),
                    (221.0, 113.0),
                ],
                true,
            );
            path(
                1,
                &[
                    (137.0, 222.0),
                    (122.0, 334.0),
                    (133.0, 323.0),
                    (147.0, 323.0),
                    (159.0, 334.0),
                ],
                true,
            );
            path(
                1,
                &[
                    (137.0, 505.0),
                    (122.0, 395.0),
                    (133.0, 405.0),
                    (147.0, 405.0),
                    (159.0, 395.0),
                ],
                true,
            );
        }
        let (cx, cy, rx, ry) = if end_cap {
            (153.0, 135.0, 23.5, 23.5)
        } else {
            (141.0, 364.0, 16.5, 20.5)
        };
        let circle = (0..32)
            .map(|i| {
                let angle = i as f32 * std::f32::consts::TAU / 32.0;
                (cx + rx * angle.cos(), cy + ry * angle.sin())
            })
            .collect::<Vec<_>>();
        path(2, &circle, true);
    }
    // Paint fine outlines before the solid ribbons to preserve the over/under weave.
    Visual::Group {
        children: [0, 2, 1]
            .into_iter()
            .map(|layer| VisualBrushChild {
                bounds,
                visual: Visual::PaintedShape {
                    geometry: Geometry::Path {
                        fill_rule: FillRule::NonZero,
                        commands: std::mem::take(&mut paths[layer]),
                    },
                    fill: match layer {
                        0 => Paint::Solid(0xffff_ffff),
                        1 => Paint::Solid(border.color),
                        _ => Paint::None,
                    },
                    stroke: if layer == 2 {
                        Paint::Solid(border.color)
                    } else {
                        Paint::None
                    },
                    stroke_width: if layer == 2 { thickness / 268.0 } else { 0.0 },
                },
            })
            .collect(),
    }
}

fn page_border_emoji_visual(
    border: DocxBorder,
    emoji: &str,
    length: f32,
    vertical: bool,
) -> Visual {
    let step = border.width.max(border.stroke_width).max(1.0);
    let count = (length / step).floor().clamp(1.0, 2_048.0) as usize;
    Visual::TextLayout {
        layout: TextLayout {
            orientation: if vertical {
                TextOrientation::StackedRl
            } else {
                TextOrientation::Horizontal
            },
            vertical_align: TextVerticalAlign::Center,
            inset_left: 0.0,
            inset_right: 0.0,
            inset_top: 0.0,
            inset_bottom: 0.0,
            wrap: false,
            ..TextLayout::default()
        },
        visual: Box::new(Visual::RichText {
            geometry: Geometry::Rectangle,
            fill: Paint::None,
            stroke: Paint::None,
            stroke_width: 0.0,
            align: TextAlign::Center,
            line_height: step,
            runs: vec![TextRun {
                paint: None,
                east_asian_line_breaks: true,
                text: emoji.repeat(count),
                font_family: "Segoe UI Symbol".to_owned(),
                font_size: step * 0.8,
                color: border.color,
                bold: false,
                italic: false,
                underline: false,
                strikethrough: false,
                highlight: 0,
                baseline_shift: 0.0,
                letter_spacing: 0.0,
                horizontal_scale: 1.0,
            }],
        }),
    }
}

fn is_nonprinting_control(character: char) -> bool {
    ('\u{007f}'..='\u{009f}').contains(&character)
}

#[derive(Clone, Copy, Debug)]
struct PageSpec {
    width: f32,
    height: f32,
    margin_top: f32,
    margin_right: f32,
    margin_bottom: f32,
    margin_left: f32,
    gutter: f32,
    rtl_gutter: bool,
    mirror_margins: bool,
    margin_top_exact: bool,
    margin_bottom_exact: bool,
    header_distance: f32,
    footer_distance: f32,
    column_count: u32,
    column_spacing: f32,
    line_pitch: Option<f32>,
}

impl Default for PageSpec {
    fn default() -> Self {
        Self {
            width: DEFAULT_PAGE_WIDTH_TWIPS as f32 / TWIPS_PER_CSS_PIXEL,
            height: DEFAULT_PAGE_HEIGHT_TWIPS as f32 / TWIPS_PER_CSS_PIXEL,
            margin_top: DEFAULT_MARGIN_TWIPS as f32 / TWIPS_PER_CSS_PIXEL,
            margin_right: DEFAULT_MARGIN_TWIPS as f32 / TWIPS_PER_CSS_PIXEL,
            margin_bottom: DEFAULT_MARGIN_TWIPS as f32 / TWIPS_PER_CSS_PIXEL,
            margin_left: DEFAULT_MARGIN_TWIPS as f32 / TWIPS_PER_CSS_PIXEL,
            gutter: 0.0,
            rtl_gutter: false,
            mirror_margins: false,
            margin_top_exact: false,
            margin_bottom_exact: false,
            header_distance: DEFAULT_HEADER_FOOTER_DISTANCE_TWIPS as f32 / TWIPS_PER_CSS_PIXEL,
            footer_distance: DEFAULT_HEADER_FOOTER_DISTANCE_TWIPS as f32 / TWIPS_PER_CSS_PIXEL,
            column_count: 1,
            column_spacing: 48.0,
            line_pitch: None,
        }
    }
}

impl PageSpec {
    fn for_page(mut self, index: usize) -> Self {
        if self.mirror_margins && index % 2 == 1 {
            std::mem::swap(&mut self.margin_left, &mut self.margin_right);
        }
        self
    }

    fn content_width(self) -> f32 {
        self.width - self.margin_left - self.margin_right
    }

    fn content_height(self) -> f32 {
        self.height - self.margin_top - self.margin_bottom
    }

    fn column_width(self) -> f32 {
        let gaps = self.column_count.saturating_sub(1) as f32 * self.column_spacing;
        (self.content_width() - gaps) / self.column_count as f32
    }

    fn column_x(self, index: u32) -> f32 {
        self.margin_left + index as f32 * (self.column_width() + self.column_spacing)
    }

    fn validate(self, limits: Limits, part: &str) -> Result<(), Diagnostic> {
        if !self.width.is_finite()
            || !self.height.is_finite()
            || !self.margin_top.is_finite()
            || !self.margin_right.is_finite()
            || !self.margin_bottom.is_finite()
            || !self.margin_left.is_finite()
            || !self.header_distance.is_finite()
            || !self.footer_distance.is_finite()
            || self.width <= 0.0
            || self.height <= 0.0
            || self.header_distance < 0.0
            || self.footer_distance < 0.0
            || self.content_width() < 1.0
            || self.content_height() < 1.0
            || self.column_count == 0
            || !self.column_spacing.is_finite()
            || self.column_spacing < 0.0
            || self
                .line_pitch
                .is_some_and(|line_pitch| !line_pitch.is_finite() || line_pitch <= 0.0)
            || self.column_width() < 1.0
        {
            return Err(format_error(part, "DOCX page size or margins are invalid"));
        }
        let pixels = f64::from(self.width.ceil()) * f64::from(self.height.ceil());
        if !pixels.is_finite() || pixels > limits.max_render_pixels as f64 {
            return Err(Diagnostic::fatal(
                DiagnosticCode::LayoutBudgetExceeded,
                Phase::Layout,
                None,
                "DOCX page dimensions exceed the configured render-pixel limit",
            )
            .in_part(part));
        }
        Ok(())
    }
}

