#[derive(Clone, Debug, Default)]
struct TableStyleProperties {
    cell_margins: [Option<f32>; 4],
    preferred_width: Option<f32>,
    preferred_width_fraction: Option<f32>,
    borders: CellBorders,
    align: Option<TextAlign>,
    border_color: Option<u32>,
    border_width: Option<f32>,
    border_compound: Option<LineCompound>,
    outer_border_width: Option<f32>,
    outer_border_compound: Option<LineCompound>,
    top_border_width: Option<f32>,
    top_border_compound: Option<LineCompound>,
    bottom_border_width: Option<f32>,
    bottom_border_compound: Option<LineCompound>,
}

impl TableStyleProperties {
    fn overlay(&mut self, other: &Self) {
        for (margin, other) in self.cell_margins.iter_mut().zip(other.cell_margins) {
            if other.is_some() {
                *margin = other;
            }
        }
        if other.preferred_width.is_some() {
            self.preferred_width = other.preferred_width;
            self.preferred_width_fraction = None;
        }
        if other.preferred_width_fraction.is_some() {
            self.preferred_width_fraction = other.preferred_width_fraction;
            self.preferred_width = None;
        }
        self.borders.overlay(&other.borders);
        if other.align.is_some() {
            self.align = other.align;
        }
        if other.border_color.is_some() {
            self.border_color = other.border_color;
        }
        if other.border_width.is_some() {
            self.border_width = other.border_width;
        }
        if other.border_compound.is_some() {
            self.border_compound = other.border_compound;
        }
        if other.outer_border_width.is_some() {
            self.outer_border_width = other.outer_border_width;
        }
        if other.outer_border_compound.is_some() {
            self.outer_border_compound = other.outer_border_compound;
        }
        if other.top_border_width.is_some() {
            self.top_border_width = other.top_border_width;
        }
        if other.top_border_compound.is_some() {
            self.top_border_compound = other.top_border_compound;
        }
        if other.bottom_border_width.is_some() {
            self.bottom_border_width = other.bottom_border_width;
        }
        if other.bottom_border_compound.is_some() {
            self.bottom_border_compound = other.bottom_border_compound;
        }
    }
}

// Word conditional styles include paragraph/run properties and explicit nil borders;
// DrawingML table styles have a different cascade and do not use Word's cnfStyle.
