impl ConditionalTableStyle {
    fn overlay(&mut self, other: &Self) {
        self.paragraph.overlay(&other.paragraph);
        self.borders.overlay(&other.borders);
        if other.fill.is_some() {
            self.fill.clone_from(&other.fill);
        }
    }
}

