impl FieldDateTime {
    fn date(self) -> String {
        format!("{}/{}/{:02}", self.month, self.day, self.year % 100)
    }

    fn time(self) -> String {
        let suffix = if self.hour < 12 { "AM" } else { "PM" };
        let hour = match self.hour % 12 {
            0 => 12,
            hour => hour,
        };
        format!("{hour}:{:02} {suffix}", self.minute)
    }

    fn formatted(self, picture: &str) -> String {
        const MONTHS: [&str; 12] = [
            "January",
            "February",
            "March",
            "April",
            "May",
            "June",
            "July",
            "August",
            "September",
            "October",
            "November",
            "December",
        ];
        const WEEKDAYS: [&str; 7] = [
            "Sunday",
            "Monday",
            "Tuesday",
            "Wednesday",
            "Thursday",
            "Friday",
            "Saturday",
        ];
        let month = self
            .month
            .checked_sub(1)
            .and_then(|month| MONTHS.get(month as usize));
        let weekday = (1..=12).contains(&self.month).then(|| {
            let offsets = [0_i64, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
            let mut year = i64::from(self.year);
            if self.month < 3 {
                year -= 1;
            }
            WEEKDAYS[((year + year / 4 - year / 100
                + year / 400
                + offsets[self.month as usize - 1]
                + i64::from(self.day))
            .rem_euclid(7)) as usize]
        });
        let mut result = String::new();
        let chars = picture.chars().collect::<Vec<_>>();
        let mut index = 0;
        while index < chars.len() {
            let character = chars[index];
            let mut count = 1;
            while chars.get(index + count) == Some(&character) {
                count += 1;
            }
            let value = match (character, count) {
                ('d', 1) => Some(self.day.to_string()),
                ('d', 2) => Some(format!("{:02}", self.day)),
                ('d', 3) => weekday.map(|name| name[..3].to_owned()),
                ('d', _) => weekday.map(str::to_owned),
                ('M', 1) => Some(self.month.to_string()),
                ('M', 2) => Some(format!("{:02}", self.month)),
                ('M', 3) => month.map(|name| name[..3].to_owned()),
                ('M', _) => month.map(|name| (*name).to_owned()),
                ('y', 2) => Some(format!("{:02}", self.year % 100)),
                ('y', _) => Some(self.year.to_string()),
                _ => None,
            };
            if let Some(value) = value {
                result.push_str(&value);
            } else {
                result.extend(chars[index..index + count].iter());
            }
            index += count;
        }
        result
    }
}

#[derive(Clone, Copy, Debug)]
struct InstructionRun {
    start: usize,
    end: usize,
    baseline_shift: f32,
}

impl ComplexFieldState {
    fn append_instruction(&mut self, text: &str, style: Option<&TextStyle>) {
        let start = self.instruction.len();
        self.instruction.push_str(text);
        let end = self.instruction.len();
        let baseline_shift = style.map_or(0.0, |style| style.baseline_shift);
        if start < end && baseline_shift != 0.0 {
            self.instruction_runs.push(InstructionRun {
                start,
                end,
                baseline_shift,
            });
        }
    }
}

