enum FrameWrap {
    None,
    NotBeside,
    #[default]
    Around,
    Tight,
    Through,
}

fn frame_wrap(value: Option<&str>) -> FrameWrap {
    match value {
        Some("none") => FrameWrap::None,
        Some("notBeside") => FrameWrap::NotBeside,
        Some("tight") => FrameWrap::Tight,
        Some("through") => FrameWrap::Through,
        _ => FrameWrap::Around,
    }
}

impl ParagraphFrame {
    fn y_from(self, text_anchor: f32) -> f32 {
        if self.relative_to_text {
            text_anchor + self.y
        } else {
            self.y
        }
    }
}

