        let bytes = stored_zip(&[
            (PART, br#"<w:document xmlns:w="w" xmlns:r="r" xmlns:wp="wp" xmlns:a="a" xmlns:c="c"><w:body><w:p><w:r><w:drawing><wp:inline><wp:extent cx="3368205" cy="2441050"/><a:graphic><a:graphicData><c:chart r:id="rIdChart"/></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p><w:sectPr/></w:body></w:document>"#),
            ("word/_rels/document.xml.rels", br#"<Relationships><Relationship Id="rIdChart" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/chart" Target="charts/chart1.xml"/></Relationships>"#),
            ("word/charts/chart1.xml", chart),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
