    #[test]
    fn real_ruby_preserves_annotation_above_base() {
        let package = Package::open(
            include_bytes!("../../tests/fixtures/ooxml-ruby.docx"),
            Limits::default(),
        )
        .unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        assert!(
            document
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.message.contains("vertical DOCX ruby"))
        );
        for (base, annotation) in [
            ("鬼門", "きもん"),
            ("方角", "ほうがく"),
            ("凝視", "ぎょうし"),
        ] {
            let reading = document
                .objects
                .iter()
                .find(|object| object.text.as_deref() == Some(annotation))
                .expect("missing annotation");
            let base = document
                .objects
                .iter()
                .find(|object| {
                    object.text.as_deref() == Some(base)
                        && object.parent_numeric_id == reading.parent_numeric_id
                })
                .expect("missing base");
            assert!(reading.bounds.y < base.bounds.y);
            assert!(reading.bounds.height < base.bounds.height);
            assert!(
                (reading.bounds.x + reading.bounds.width / 2.0
                    - base.bounds.x
                    - base.bounds.width / 2.0)
                    .abs()
                    < 0.01
            );
        }
    }

    #[test]
    fn combined_text_groups_ids_and_preserves_style_and_explicit_disable() {
        let theme = super::DocxTheme::default();
        let styles = super::parse_styles_xml(br#"<w:styles xmlns:w="w"><w:style w:type="character" w:styleId="combined"><w:rPr><w:sz w:val="30"/><w:eastAsianLayout w:id="7" w:combine="1"/></w:rPr></w:style></w:styles>"#, Limits::default(), "word/styles.xml", &theme).unwrap();
        let xml = r#"<w:document xmlns:w="w"><w:body><w:p>
          <w:r><w:rPr><w:rStyle w:val="combined"/></w:rPr><w:t>甲乙</w:t><w:t>丙丁</w:t></w:r>
          <w:r><w:rPr><w:rStyle w:val="combined"/><w:b/></w:rPr><w:t>戊己庚辛</w:t></w:r>
          <w:r><w:rPr><w:sz w:val="30"/><w:eastAsianLayout w:id="8" w:combine="1"/></w:rPr><w:t>子丑寅卯</w:t></w:r>
          <w:r><w:rPr><w:rStyle w:val="combined"/><w:eastAsianLayout w:combine="0"/></w:rPr><w:t>不合并</w:t></w:r>
        </w:p></w:body></w:document>"#;
        let mut parsed = super::parse_document_xml_with_styles(
            xml.as_bytes(),
            Limits::default(),
            PART,
            Vec::new(),
            &styles,
            &theme,
        )
        .unwrap();
        let Block::Paragraph(paragraph) = &parsed.blocks[0] else {
            panic!("paragraph expected")
        };
        assert_eq!(paragraph.drawings.len(), 2);
        assert!(paragraph.text.ends_with("不合并"));
        let equation = paragraph.drawings[0].equation_field.as_ref().unwrap();
        assert_eq!(equation.expression.plain_text(), "甲乙丙丁戊己庚辛");
        let layout = equation.layout(&FontMetricTable::default());
        assert_eq!(layout.children.len(), 2);
        assert!(layout.children[0].bounds.y < layout.children[1].bounds.y);
        for (index, child) in layout.children.iter().enumerate() {
            let Visual::TextLayout { visual, .. } = &child.visual else {
                panic!("text expected")
            };
            let Visual::RichText { runs, .. } = visual.as_ref() else {
                panic!("runs expected")
            };
            assert_eq!(runs[0].bold, index == 1);
            assert_eq!(runs[0].font_size, 10.0);
        }
        assert_eq!(
            paragraph.drawings[1]
                .equation_field
                .as_ref()
                .unwrap()
                .expression
                .plain_text(),
            "子丑寅卯"
        );
        let combined = super::EquationNode::CombinedText(vec![(
            "利润总额+税金总额+利息支出                   平均资产总额    ".to_owned(),
            super::TextStyle::default(),
        )]);
        let narrow_space = single_font_metric("Times New Roman", ' ', 0.2);
        let layout = combined.layout(&super::TextStyle::default(), &narrow_space);
        assert_eq!(
            super::equation_part_text(&layout.children[0].visual)
                .unwrap()
                .trim(),
            "利润总额+税金总额+利息支出"
        );
        assert_eq!(
            super::equation_part_text(&layout.children[1].visual)
                .unwrap()
                .trim(),
            "平均资产总额"
        );
        let fallback = font_metric_with_line_height("Times New Roman", ' ', 0.2, 1.15, true);
        let nominal = combined.layout(&super::TextStyle::default(), &FontMetricTable::default());
        let substituted = combined.layout(&super::TextStyle::default(), &fallback);
        assert!(
            (substituted.advance - nominal.advance).abs() < 0.01,
            "fallback spaces must not collapse the authored inline advance"
        );
        parsed.sections[0].headers.default = Some(super::Story {
            is_separator: false,
            part: "word/header1.xml".to_owned(),
            blocks: parsed.blocks.clone(),
            paragraphs: vec![*paragraph.clone()],
            images: Default::default(),
            charts: Default::default(),
            has_reference_marker: false,
            reference_number: 0,
        });
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let header_lines = document
            .objects
            .iter()
            .filter(|object| {
                object.source.part == "word/header1.xml"
                    && object.kind == ObjectKind::TextBox
                    && object.stable_id.contains(":equation:")
            })
            .count();
        assert_eq!(
            header_lines, 4,
            "both combined runs must render in the header as well"
        );
    }

    #[test]
    fn supplied_2007_combined_formula_text_stays_on_two_small_lines() {
        let package = Package::open(
            include_bytes!("../../tests/fixtures/word-2007-table.docx"),
            Limits::default(),
        )
        .unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        for (numerator, denominator) in [
            ("利润总额", "成本费用总额"),
            ("利润总额+税金总额+利息支出", "平均资产总额"),
            ("当年新产品产值", "当年总产值"),
        ] {
            let top = document
                .objects
                .iter()
                .find(|object| {
                    object.kind == ObjectKind::TextBox
                        && object
                            .text
                            .as_deref()
                            .is_some_and(|text| text.trim() == numerator)
                })
                .expect("combined numerator must be rendered as its own small line");
            let bottom = document
                .objects
                .iter()
                .find(|object| {
                    object.kind == ObjectKind::TextBox
                        && object
                            .text
                            .as_deref()
                            .is_some_and(|text| text.trim() == denominator)
                })
                .expect("combined denominator must be rendered as its own small line");
            assert_eq!(top.parent_numeric_id, bottom.parent_numeric_id);
            assert_eq!(top.unit_index, bottom.unit_index);
            assert!(top.bounds.y < bottom.bounds.y);
            assert!(bottom.bounds.y - top.bounds.y <= 12.0);
            for object in [top, bottom] {
                let Visual::TextLayout { visual, .. } = &object.visual else {
                    panic!("text layout expected")
                };
                let Visual::RichText { runs, .. } = visual.as_ref() else {
                    panic!("rich text expected")
                };
                assert!(runs.iter().all(|run| (run.font_size - 10.0).abs() < 0.01));
            }
            let group = &document.objects[top.parent_numeric_id.unwrap() as usize];
            let paragraph = &document.objects[group.parent_numeric_id.unwrap() as usize];
            assert!(paragraph.text.as_deref().unwrap().contains("×100%"));
            assert!(
                paragraph.bounds.height < 50.0,
                "formula must remain inline: {:?}",
                paragraph.bounds
            );
            let bar = document.objects.iter().find(|object| {
                object.kind == ObjectKind::Shape && object.bounds.width > 50.0 && object.bounds.height < 2.0
                    && matches!((&object.source.locator, &paragraph.source.locator),
                        (SourceLocator::Docx { paragraph_index: a, .. }, SourceLocator::Docx { paragraph_index: b, .. }) if a == b)
            }).expect("authored VML fraction bar must survive");
            assert_eq!(
                bar.unit_index, top.unit_index,
                "fraction bar must follow its paragraph onto the next page"
            );
            assert!((bar.bounds.y - bottom.bounds.y).abs() < 2.0);
        }
    }

