    #[test]
    fn renders_real_ink2_vml_curves_in_docx_with_coordinate_origin() {
        let source = Package::open(
            include_bytes!("../../tests/fixtures/Ink2.pptx"),
            Limits::default(),
        )
        .unwrap();
        let vml = source
            .required_part("ppt/drawings/vmlDrawing1.vml")
            .unwrap();
        let vml = std::str::from_utf8(&vml).unwrap();
        let start = vml.find("<v:shape ").unwrap();
        let end = vml[start..].find("</v:shape>").unwrap() + start + "</v:shape>".len();
        let xml = format!(
            r#"<w:document xmlns:w="w" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:p="urn:schemas-microsoft-com:office:powerpoint"><w:body><w:p><w:r><w:pict>{}</w:pict></w:r></w:p></w:body></w:document>"#,
            &vml[start..end]
        );
        let bytes = stored_zip(&[(PART, xml.as_bytes())]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let commands = document
            .objects
            .iter()
            .find_map(|o| match &o.visual {
                Visual::PaintedShape {
                    geometry: Geometry::Path { commands, .. },
                    ..
                } => Some(commands),
                _ => None,
            })
            .expect("real VML ink path must also render in DOCX");
        assert_eq!(
            commands
                .iter()
                .filter(|c| matches!(c, PathCommand::MoveTo { .. }))
                .count(),
            13
        );
        assert!(
            commands
                .iter()
                .any(|c| matches!(c, PathCommand::BezierCurveTo { .. }))
        );
        assert!(
            matches!(commands[0], PathCommand::MoveTo { x, y } if x < 1.0 && y > 40.0 && y < 42.0)
        );
    }

    #[test]
    fn renders_direct_vml_paths_with_authored_paint() {
        let document_xml = br##"<w:document xmlns:w="w" xmlns:v="v" xmlns:o="o"><w:body><w:p><w:r>
          <v:shapetype id="freeform" o:spt="0"/>
          <w:pict>
            <v:shape type="#freeform" style="width:102pt;height:54pt" coordsize="20000,20000"
              path="m10000,l20000,10000,10000,20000,0,10000,10000,0xe"
              fillcolor="#396" strokecolor="red"/>
          </w:pict>
          <w:pict>
            <v:shape style="width:128.25pt;height:41.25pt" coordsize="20000,20000"
              path="m,l20000,r,20000l,20000,,xe" fillcolor="#369" stroked="f"/>
          </w:pict>
        </w:r></w:p></w:body></w:document>"##;
        let bytes = stored_zip(&[(PART, document_xml)]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let shapes = document
            .objects
            .iter()
            .filter_map(|object| match &object.visual {
                Visual::PaintedShape {
                    geometry,
                    fill,
                    stroke,
                    ..
                } => Some((geometry, fill, stroke)),
                _ => None,
            })
            .collect::<Vec<_>>();

        assert!(matches!(shapes[0], (
            Geometry::Path { commands, .. },
            Paint::Solid(0x3399_66ff),
            Paint::Solid(0xff00_00ff),
        ) if commands.len() == 6));
        assert!(matches!(shapes[1], (
            Geometry::Path { commands, .. },
            Paint::Solid(0x3366_99ff),
            Paint::None,
        ) if commands.len() == 6));
    }

