    #[test]
    fn nested_table_flow_preserves_order_images_and_fixed_width_in_both_hosts() {
        for fixed in [false, true] {
            for textbox in [false, true] {
                let layout = if fixed { "fixed" } else { "autofit" };
                let table = format!(
                    r#"<w:tbl><w:tblPr><w:tblW w:w="6000" w:type="dxa"/></w:tblPr>
                    <w:tblGrid><w:gridCol w:w="6000"/></w:tblGrid><w:tr><w:tc>
                    <w:p><w:r><w:t>before</w:t></w:r></w:p>
                    <w:tbl><w:tblPr><w:tblW w:w="1500" w:type="dxa"/><w:tblLayout w:type="{layout}"/><w:jc w:val="center"/>
                    <w:tblBorders><w:top w:val="single" w:sz="8" w:color="FF0000"/></w:tblBorders></w:tblPr>
                    <w:tblGrid><w:gridCol w:w="3000"/></w:tblGrid><w:tr><w:tc>
                    <w:p><w:r><w:t>inside</w:t></w:r></w:p>
                    <w:p><w:r><w:pict><v:shape style="width:12pt;height:15pt"><v:imagedata r:id="image"/></v:shape></w:pict></w:r></w:p>
                    </w:tc></w:tr></w:tbl>
                    <w:p><w:r><w:t>after</w:t></w:r></w:p></w:tc></w:tr></w:tbl>"#
                );
                let body = if textbox {
                    format!(
                        r#"<w:p><w:r><w:pict><v:shape style="width:300pt;height:300pt"><v:textbox inset="0,0,0,0"><w:txbxContent>{table}</w:txbxContent></v:textbox></v:shape></w:pict></w:r></w:p>"#
                    )
                } else {
                    table
                };
                let xml = format!(
                    r#"<w:document xmlns:w="w" xmlns:v="v" xmlns:r="r"><w:body>{body}</w:body></w:document>"#
                );
                let bytes = stored_zip(&[(PART, xml.as_bytes()),
                    ("word/_rels/document.xml.rels", br#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="image" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/image.png"/></Relationships>"#),
                    ("word/media/image.png", b"\x89PNG\r\n\x1a\nimage")]);
                let package = Package::open(&bytes, Limits::default()).unwrap();
                let document = parse(&package, PART, Vec::new()).unwrap();
                let tables = document
                    .objects
                    .iter()
                    .filter(|o| o.kind == ObjectKind::Table)
                    .collect::<Vec<_>>();
                assert_eq!(tables.len(), 2);
                let nested = tables[1];
                assert!((nested.bounds.width - if fixed { 100.0 } else { 200.0 }).abs() < 0.01);
                let parent = &document.objects[nested.parent_numeric_id.unwrap() as usize];
                assert!(
                    (nested.bounds.x
                        - parent.bounds.x
                        - (parent.bounds.width - nested.bounds.width) / 2.0)
                        .abs()
                        < 0.01
                );
                let find = |text| {
                    document
                        .objects
                        .iter()
                        .find(|o| {
                            o.kind == ObjectKind::Paragraph && o.text.as_deref() == Some(text)
                        })
                        .unwrap()
                };
                let before = find("before");
                let inside = find("inside");
                let after = find("after");
                assert!(before.bounds.y + before.bounds.height <= nested.bounds.y + 0.01);
                assert!(nested.bounds.y + nested.bounds.height <= after.bounds.y + 0.01);
                assert!(inside.bounds.y >= nested.bounds.y);
                let image = document
                    .objects
                    .iter()
                    .find(|o| matches!(&o.visual, Visual::Image { .. }))
                    .expect("nested image relationship must be resolved");
                assert!(image.bounds.y >= inside.bounds.y + inside.bounds.height - 0.01);
                assert!(
                    image.bounds.y + image.bounds.height
                        <= nested.bounds.y + nested.bounds.height + 0.01
                );
                assert!(
                    document
                        .objects
                        .iter()
                        .any(|o| o.parent_numeric_id == Some(nested.numeric_id)
                            && o.stable_id.ends_with(":border:top"))
                );
            }
        }
    }

    #[test]
    fn nested_cell_end_marker_collapses_without_dropping_real_empty_lines() {
        let height = |tail: &str| {
            let xml = format!(
                r#"<w:document xmlns:w="w"><w:body><w:tbl><w:tr><w:tc>
                <w:tbl><w:tr><w:tc><w:p><w:r><w:t>inside</w:t></w:r></w:p></w:tc></w:tr></w:tbl>
                {tail}</w:tc></w:tr></w:tbl></w:body></w:document>"#
            );
            let parsed =
                parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new()).unwrap();
            let document = layout_document(parsed, Limits::default(), PART).unwrap();
            document
                .objects
                .iter()
                .find(|o| o.kind == ObjectKind::Table)
                .unwrap()
                .bounds
                .height
        };
        // Word native marker-probe.docx confirms that real text adds a line,
        // while the single required empty paragraph after the inner table does not.
        let empty = height("<w:p/>");
        let text = height("<w:p><w:r><w:t>MARK</w:t></w:r></w:p>");
        assert!(text > empty + 10.0);
        assert!(height("<w:p/><w:p/>") > empty + 10.0);
        assert!(
            height(
                r#"<w:p><w:pPr><w:pBdr><w:bottom w:val="single" w:sz="8"/></w:pBdr></w:pPr></w:p>"#
            ) > empty + 10.0
        );
    }

