    #[test]
    fn custom_note_marks_do_not_consume_automatic_numbers() {
        for (reference, entry_name, marker) in [
            ("footnoteReference", "footnote", "footnoteRef"),
            ("endnoteReference", "endnote", "endnoteRef"),
        ] {
            let xml = format!(
                r#"<w:document xmlns:w="w"><w:body><w:p><w:r>
              <w:{reference} w:id="8" w:customMarkFollows="1"/><w:sym w:font="Symbol" w:char="F02A"/>
              <w:{reference} w:id="9"/><w:{reference} w:id="10" w:customMarkFollows="0"/>
            </w:r></w:p></w:body></w:document>"#
            );
            let parsed =
                parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new()).unwrap();
            let Block::Paragraph(paragraph) = &parsed.blocks[0] else {
                panic!("paragraph")
            };
            assert_eq!(
                paragraph.text,
                if entry_name == "footnote" {
                    "∗12"
                } else {
                    "∗iii"
                }
            );
            let numbers = paragraph
                .references
                .iter()
                .map(|r| (r.id, r.number))
                .collect();
            let notes = format!(
                r#"<w:notes xmlns:w="w"><w:{entry_name} w:id="8"><w:p><w:r><w:sym w:font="Symbol" w:char="F02A"/><w:t> Custom</w:t></w:r></w:p></w:{entry_name}><w:{entry_name} w:id="9"><w:p><w:r><w:{marker}/><w:t> Auto</w:t></w:r></w:p></w:{entry_name}></w:notes>"#
            );
            let stories = super::parse_story_collection_xml_with_styles(
                notes.as_bytes(),
                Limits::default(),
                PART,
                entry_name,
                &super::Styles::default(),
                &super::DocxTheme::default(),
                &numbers,
            )
            .unwrap();
            assert_eq!(stories[&8].paragraphs[0].text, "∗ Custom");
            assert!(stories[&8].has_reference_marker);
            assert_eq!(
                stories[&9].paragraphs[0].text,
                if entry_name == "footnote" {
                    "1 Auto"
                } else {
                    "i Auto"
                }
            );
        }
    }

    #[test]
    fn nested_floating_table_offset_expands_its_merged_cell() {
        let bytes = stored_zip(&[(
            PART,
            br#"<w:document xmlns:w="w"><w:body><w:tbl>
              <w:tblGrid><w:gridCol w:w="2400"/><w:gridCol w:w="2400"/></w:tblGrid>
              <w:tr><w:tc><w:p><w:r><w:t>first</w:t></w:r></w:p></w:tc><w:tc>
                <w:tcPr><w:vMerge w:val="restart"/></w:tcPr>
                <w:tbl><w:tblPr><w:tblpPr w:vertAnchor="text" w:tblpY="600"/></w:tblPr>
                  <w:tblGrid><w:gridCol w:w="1200"/></w:tblGrid>
                  <w:tr><w:tc><w:p/></w:tc></w:tr>
                </w:tbl><w:p/>
              </w:tc></w:tr>
              <w:tr><w:tc><w:p><w:r><w:t>second</w:t></w:r></w:p></w:tc>
                <w:tc><w:tcPr><w:vMerge/></w:tcPr><w:p/></w:tc>
              </w:tr>
            </w:tbl><w:sectPr/></w:body></w:document>"#,
        )]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let merged = document
            .objects
            .iter()
            .find(|object| {
                object.kind == ObjectKind::Cell
                    && matches!(
                        object.source.locator,
                        SourceLocator::Docx {
                            row: Some(0),
                            column: Some(1),
                            ..
                        }
                    )
            })
            .unwrap();
        let nested = document
            .objects
            .iter()
            .find(|object| {
                object.kind == ObjectKind::Table
                    && object.parent_numeric_id == Some(merged.numeric_id)
            })
            .unwrap();

        assert!(nested.bounds.y >= merged.bounds.y + 40.0 - 0.01);
        assert!(
            nested.bounds.y + nested.bounds.height <= merged.bounds.y + merged.bounds.height + 0.01,
            "the merged cell must include the positioned nested table: {:?} inside {:?}",
            nested.bounds,
            merged.bounds
        );
    }

