    #[test]
    fn word_verified_inline_images_share_a_line_and_reserve_their_height() {
        // Both packages were exported by Word: the pair shares one line and the
        // textbox's following paragraph is below the image, not underneath it.
        for (bytes, count) in [
            (
                include_bytes!("../../tests/fixtures/inline-images-table.docx").as_slice(),
                2,
            ),
            (
                include_bytes!("../../tests/fixtures/inline-images-textbox.docx").as_slice(),
                1,
            ),
        ] {
            let package = Package::open(bytes, Limits::default()).unwrap();
            let document = parse(&package, PART, Vec::new()).unwrap();
            assert_inline_image_flow(&document, count, false);
            let authored_image = package.required_part("word/media/image1.png").unwrap();
            for image in document
                .objects
                .iter()
                .filter(|o| o.kind == ObjectKind::Image)
            {
                assert!(
                    matches!(&image.visual, Visual::Image { media_type, bytes, .. }
                    if media_type == "image/png" && bytes.as_slice() == &authored_image[..]),
                    "{} must render the authored image, not a placeholder",
                    image.stable_id
                );
            }
        }
    }

    fn assert_inline_image_flow(document: &crate::model::Document, count: usize, wrapped: bool) {
        let images = document
            .objects
            .iter()
            .filter(|o| o.kind == ObjectKind::Image)
            .collect::<Vec<_>>();
        assert_eq!(images.len(), count);
        let after = document
            .objects
            .iter()
            .find(|o| o.kind == ObjectKind::Paragraph && o.text.as_deref() == Some("After logo"))
            .unwrap();
        for image in &images {
            assert!(
                after.bounds.y + 0.01 >= image.bounds.y + image.bounds.height,
                "following text {:?} overlaps image {:?}",
                after.bounds,
                image.bounds
            );
        }
        for pair in images.windows(2) {
            let (a, b) = (pair[0].bounds, pair[1].bounds);
            if wrapped {
                assert!(b.y + 0.01 >= a.y + a.height, "{a:?} {b:?}");
            } else {
                assert!(
                    (a.y + a.height - b.y - b.height).abs() < 0.01,
                    "{a:?} {b:?}"
                );
                assert!(b.x + 0.01 >= a.x + a.width, "{a:?} {b:?}");
            }
        }
    }

    #[test]
    fn nested_inline_images_use_story_resources_and_tolerate_missing_parts() {
        let fixture = Package::open(
            include_bytes!("../../tests/fixtures/inline-images-textbox.docx"),
            Limits::default(),
        )
        .unwrap();
        let xml = fixture.required_part(PART).unwrap();
        let xml = std::str::from_utf8(&xml).unwrap();
        let content = xml
            .split("<w:body>")
            .nth(1)
            .unwrap()
            .split("<w:sectPr>")
            .next()
            .unwrap();
        let image = fixture.required_part("word/media/image1.png").unwrap();
        let image_relationships = fixture
            .required_part("word/_rels/document.xml.rels")
            .unwrap();
        for kind in ["header", "footer"] {
            for present in [true, false] {
                let body = format!(
                    r#"<w:document xmlns:w="w" xmlns:r="r"><w:body><w:p><w:r><w:t>Body</w:t></w:r></w:p><w:sectPr><w:{kind}Reference w:type="default" r:id="rIdStory"/><w:pgMar w:top="5000" w:bottom="5000" w:left="1440" w:right="1440"/></w:sectPr></w:body></w:document>"#
                );
                let relationships = format!(
                    r#"<Relationships><Relationship Id="rIdStory" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/{kind}" Target="{kind}.xml"/></Relationships>"#
                );
                let root = if kind == "header" { "hdr" } else { "ftr" };
                let story = format!(
                    r#"<w:{root} xmlns:w="w" xmlns:wp="wp" xmlns:v="v" xmlns:o="o" xmlns:a="a" xmlns:r="r" xmlns:pic="pic">{content}</w:{root}>"#
                );
                let story_part = format!("word/{kind}.xml");
                let story_rels = format!("word/_rels/{kind}.xml.rels");
                let mut parts = vec![
                    (PART, body.as_bytes()),
                    ("word/_rels/document.xml.rels", relationships.as_bytes()),
                    (story_part.as_str(), story.as_bytes()),
                    (story_rels.as_str(), &image_relationships[..]),
                ];
                if present {
                    parts.push(("word/media/image1.png", &image[..]));
                }
                let bytes = stored_zip(&parts);
                let package = Package::open(&bytes, Limits::default()).unwrap();
                let document = parse(&package, PART, Vec::new()).unwrap();
                let rendered = document
                    .objects
                    .iter()
                    .find(|o| o.kind == ObjectKind::Image && o.source.part == story_part)
                    .unwrap();
                if present {
                    assert!(
                        matches!(&rendered.visual, Visual::Image { bytes, .. } if bytes.as_slice() == &image[..]),
                        "{kind} image must use its own part's relationships"
                    );
                } else {
                    assert!(
                        document
                            .diagnostics
                            .iter()
                            .any(|d| d.message.contains("image1.png")
                                && d.message.contains("missing"))
                    );
                }
                assert!(
                    document
                        .objects
                        .iter()
                        .any(|o| o.text.as_deref() == Some("After logo"))
                );
            }
        }
    }

    #[test]
    fn inline_image_rows_flow_in_body_cells_and_nested_textboxes() {
        for width in [120, 400] {
            for host in ["body", "cell", "textbox", "textbox-cell"] {
                let image = |id| {
                    format!(
                        r#"<w:r><w:drawing><wp:inline><wp:extent cx="762000" cy="476250"/><wp:docPr id="{id}"/></wp:inline></w:drawing></w:r>"#
                    )
                };
                let paragraphs = format!(
                    "<w:p>{}{}</w:p><w:p><w:r><w:t>After logo</w:t></w:r></w:p>",
                    image(1),
                    image(2)
                );
                let table = |content| {
                    format!(
                        r#"<w:tbl><w:tblPr><w:tblCellMar><w:left w:w="0"/><w:right w:w="0"/></w:tblCellMar></w:tblPr><w:tblGrid><w:gridCol w:w="{}"/></w:tblGrid><w:tr><w:tc>{content}</w:tc></w:tr></w:tbl>"#,
                        width * 15
                    )
                };
                let textbox = |content| {
                    format!(
                        r#"<w:p><w:r><w:pict><v:shape style="position:absolute;width:{}pt;height:200pt"><v:textbox inset="0,0,0,0"><w:txbxContent>{content}</w:txbxContent></v:textbox></v:shape></w:pict></w:r></w:p>"#,
                        width * 3 / 4
                    )
                };
                let body = match host {
                    "cell" => table(paragraphs),
                    "textbox" => textbox(paragraphs),
                    "textbox-cell" => textbox(table(paragraphs)),
                    _ => paragraphs,
                };
                let xml = format!(
                    r#"<w:document xmlns:w="w" xmlns:wp="wp" xmlns:v="v"><w:body>{body}<w:sectPr><w:pgSz w:w="{}" w:h="15840"/><w:pgMar w:top="1440" w:left="1440" w:bottom="1440" w:right="1440"/></w:sectPr></w:body></w:document>"#,
                    width * 15 + 2880
                );
                let parsed =
                    parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new())
                        .unwrap();
                let document = layout_document(parsed, Limits::default(), PART).unwrap();
                assert_inline_image_flow(&document, 2, width == 120);
            }
        }
    }

    #[test]
    fn inline_image_rows_flow_in_headers_footers_and_footnotes() {
        for width in [120, 400] {
            for kind in ["header", "footer", "footnotes"] {
                let image = |id| {
                    format!(
                        r#"<w:r><w:drawing><wp:inline><wp:extent cx="762000" cy="476250"/><wp:docPr id="{id}"/></wp:inline></w:drawing></w:r>"#
                    )
                };
                let content = format!(
                    r#"<w:p><w:pPr><w:ind w:left="300"/></w:pPr>{}{}</w:p><w:p><w:r><w:t>After logo</w:t></w:r></w:p>"#,
                    image(1),
                    image(2)
                );
                let (root, content, reference, section) = if kind == "footnotes" {
                    (
                        "footnotes",
                        format!(r#"<w:footnote w:id="2">{content}</w:footnote>"#),
                        r#"<w:footnoteReference w:id="2"/>"#,
                        String::new(),
                    )
                } else {
                    (
                        if kind == "header" { "hdr" } else { "ftr" },
                        content,
                        "",
                        format!(r#"<w:{kind}Reference w:type="default" r:id="rIdStory"/>"#),
                    )
                };
                let body = format!(
                    r#"<w:document xmlns:w="w" xmlns:r="r"><w:body><w:p><w:r><w:t>Body</w:t>{reference}</w:r></w:p><w:sectPr>{section}<w:pgSz w:w="{}" w:h="15840"/><w:pgMar w:top="3000" w:left="1440" w:bottom="3000" w:right="1440"/></w:sectPr></w:body></w:document>"#,
                    width * 15 + 2880
                );
                let story = format!(r#"<w:{root} xmlns:w="w" xmlns:wp="wp">{content}</w:{root}>"#);
                let relationships = format!(
                    r#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rIdStory" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/{kind}" Target="{kind}.xml"/></Relationships>"#
                );
                let bytes = stored_zip(&[
                    (PART, body.as_bytes()),
                    ("word/_rels/document.xml.rels", relationships.as_bytes()),
                    (&format!("word/{kind}.xml"), story.as_bytes()),
                ]);
                let package = Package::open(&bytes, Limits::default()).unwrap();
                let document = parse(&package, PART, Vec::new()).unwrap();
                assert_inline_image_flow(&document, 2, width == 120);
                let image = document
                    .objects
                    .iter()
                    .find(|o| o.kind == ObjectKind::Image)
                    .unwrap();
                assert!(
                    (image.bounds.x - 116.0).abs() < 0.01,
                    "{kind}: {:?}",
                    image.bounds
                );
            }
        }
    }

    #[test]
    fn inline_image_rows_keep_alignment_baselines_and_page_boundaries() {
        for (align, offset) in [("left", 0.0), ("center", 20.0), ("right", 40.0)] {
            let xml = format!(
                r#"<w:document xmlns:w="w" xmlns:wp="wp"><w:body>
              <w:p><w:pPr><w:spacing w:line="2250" w:lineRule="exact"/></w:pPr><w:r><w:t>Prelude</w:t></w:r></w:p>
              <w:p><w:pPr><w:jc w:val="{align}"/><w:ind w:left="300" w:right="600" w:firstLine="150"/></w:pPr>
                <w:r><w:drawing><wp:inline><wp:extent cx="762000" cy="285750"/><wp:docPr id="1"/></wp:inline></w:drawing></w:r>
                <w:r><w:drawing><wp:inline><wp:extent cx="762000" cy="571500"/><wp:docPr id="2"/></wp:inline></w:drawing></w:r>
              </w:p><w:p><w:r><w:t>After logo</w:t></w:r></w:p>
              <w:sectPr><w:pgSz w:w="6930" w:h="5880"/><w:pgMar w:top="1440" w:left="1440" w:bottom="1440" w:right="1440"/></w:sectPr>
            </w:body></w:document>"#
            );
            let parsed =
                parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new()).unwrap();
            let document = layout_document(parsed, Limits::default(), PART).unwrap();
            assert_inline_image_flow(&document, 2, false);
            let images = document
                .objects
                .iter()
                .filter(|o| o.kind == ObjectKind::Image)
                .collect::<Vec<_>>();
            assert_eq!(images[0].unit_index, 1);
            assert_eq!(
                images[1].unit_index, 1,
                "one image row must stay on one page"
            );
            assert!((images[0].bounds.x - (126.0 + offset)).abs() < 0.01);
            assert!((images[1].bounds.y - 96.0).abs() < 0.01);
        }
    }

