    fn single_font_metric(family: &str, character: char, advance_em: f32) -> FontMetricTable {
        font_metrics(family, &[(character, advance_em)])
    }

    fn font_metrics(family: &str, metrics: &[(char, f32)]) -> FontMetricTable {
        let family = family.as_bytes();
        let metrics_offset = 20 + 16 + family.len();
        let mut bytes = Vec::new();
        bytes.extend_from_slice(b"OVFM");
        bytes.extend_from_slice(&1_u16.to_le_bytes());
        bytes.extend_from_slice(&20_u16.to_le_bytes());
        bytes.extend_from_slice(&1_u32.to_le_bytes());
        bytes.extend_from_slice(&(metrics.len() as u32).to_le_bytes());
        bytes.extend_from_slice(&(metrics_offset as u32).to_le_bytes());
        bytes.extend_from_slice(&(family.len() as u16).to_le_bytes());
        bytes.push(0);
        bytes.push(4);
        bytes.extend_from_slice(&400_u16.to_le_bytes());
        bytes.extend_from_slice(&0_u16.to_le_bytes());
        bytes.extend_from_slice(&0_u32.to_le_bytes());
        bytes.extend_from_slice(&(metrics.len() as u32).to_le_bytes());
        bytes.extend_from_slice(family);
        for &(character, advance_em) in metrics {
            bytes.extend_from_slice(&(character as u32).to_le_bytes());
            bytes.extend_from_slice(&advance_em.to_bits().to_le_bytes());
        }
        FontMetricTable::decode(&bytes, Limits::default()).unwrap()
    }

    fn font_metric_with_line_height(
        family: &str,
        character: char,
        advance_em: f32,
        line_height_em: f32,
        fallback: bool,
    ) -> FontMetricTable {
        let family = family.as_bytes();
        let metrics_offset = 20 + 28 + family.len();
        let mut bytes = Vec::new();
        bytes.extend_from_slice(b"OVFM");
        bytes.extend_from_slice(&2_u16.to_le_bytes());
        bytes.extend_from_slice(&20_u16.to_le_bytes());
        bytes.extend_from_slice(&1_u32.to_le_bytes());
        bytes.extend_from_slice(&1_u32.to_le_bytes());
        bytes.extend_from_slice(&(metrics_offset as u32).to_le_bytes());
        bytes.extend_from_slice(&(family.len() as u16).to_le_bytes());
        bytes.push(0);
        bytes.push(4);
        bytes.extend_from_slice(&400_u16.to_le_bytes());
        bytes.extend_from_slice(&u16::from(fallback).to_le_bytes());
        bytes.extend_from_slice(&0_u32.to_le_bytes());
        bytes.extend_from_slice(&1_u32.to_le_bytes());
        bytes.extend_from_slice(&line_height_em.to_bits().to_le_bytes());
        bytes.extend_from_slice(&0_f32.to_bits().to_le_bytes());
        bytes.extend_from_slice(&0_f32.to_bits().to_le_bytes());
        bytes.extend_from_slice(family);
        bytes.extend_from_slice(&(character as u32).to_le_bytes());
        bytes.extend_from_slice(&advance_em.to_bits().to_le_bytes());
        FontMetricTable::decode(&bytes, Limits::default()).unwrap()
    }

