    #[test]
    fn docx_chart_series_without_explicit_colors_use_the_document_theme() {
        let document_xml = br#"<w:document xmlns:w="w" xmlns:r="r" xmlns:wp="wp" xmlns:a="a" xmlns:c="c"><w:body>
          <w:p><w:r><w:drawing><wp:inline><wp:extent cx="3810000" cy="2857500"/><a:graphic><a:graphicData><c:chart r:id="rIdChart"/></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p><w:sectPr/>
        </w:body></w:document>"#;
        let relationships = br#"<Relationships>
          <Relationship Id="rIdChart" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/chart" Target="charts/chart1.xml"/>
          <Relationship Id="rIdTheme" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" Target="theme/theme1.xml"/>
        </Relationships>"#;
        let chart = br#"<c:chartSpace xmlns:c="c"><c:chart><c:plotArea><c:barChart>
          <c:ser><c:val><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:val></c:ser>
          <c:ser><c:val><c:numLit><c:pt idx="0"><c:v>2</c:v></c:pt></c:numLit></c:val></c:ser>
          <c:ser><c:val><c:numLit><c:pt idx="0"><c:v>3</c:v></c:pt></c:numLit></c:val></c:ser>
        </c:barChart></c:plotArea></c:chart></c:chartSpace>"#;
        let theme = br#"<a:theme xmlns:a="a"><a:themeElements><a:clrScheme>
          <a:accent1><a:srgbClr val="4F81BD"/></a:accent1>
          <a:accent2><a:srgbClr val="C0504D"/></a:accent2>
          <a:accent3><a:srgbClr val="9BBB59"/></a:accent3>
        </a:clrScheme></a:themeElements></a:theme>"#;
        let bytes = stored_zip(&[
            (PART, document_xml),
            ("word/_rels/document.xml.rels", relationships),
            ("word/charts/chart1.xml", chart),
            ("word/theme/theme1.xml", theme),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();

        for (row, color) in [0x4f81_bdff, 0xc050_4dff, 0x9bbb_59ff]
            .into_iter()
            .enumerate()
        {
            assert!(document.objects.iter().any(|object| {
                object.source.part == "word/charts/chart1.xml"
                    && matches!(
                        object.source.locator,
                        SourceLocator::Docx { row: Some(value), .. } if value == row as u32
                    )
                    && matches!(
                        object.visual,
                        Visual::PaintedShape { fill: Paint::Solid(value), .. } if value == color
                    )
            }));
        }
    }

    #[test]
    fn classic_docx_chart_legend_is_centered_and_uses_dark_text() {
        let document_xml = br#"<w:document xmlns:w="w" xmlns:r="r" xmlns:wp="wp" xmlns:a="a" xmlns:c="c"><w:body>
          <w:p><w:r><w:drawing><wp:inline><wp:extent cx="3810000" cy="2857500"/><a:graphic><a:graphicData><c:chart r:id="rIdChart"/></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p><w:sectPr/>
        </w:body></w:document>"#;
        let relationships = br#"<Relationships>
          <Relationship Id="rIdChart" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/chart" Target="charts/chart1.xml"/>
        </Relationships>"#;
        let chart = br#"<c:chartSpace xmlns:c="c"><c:style val="2"/><c:chart><c:plotArea><c:barChart>
          <c:ser><c:tx><c:v>Series 1</c:v></c:tx><c:val><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:val></c:ser>
        </c:barChart></c:plotArea><c:legend><c:legendPos val="r"/></c:legend></c:chart></c:chartSpace>"#;
        let bytes = stored_zip(&[
            (PART, document_xml),
            ("word/_rels/document.xml.rels", relationships),
            ("word/charts/chart1.xml", chart),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let key = document
            .objects
            .iter()
            .find(|object| object.stable_id.ends_with("legend-key-0"))
            .unwrap();
        let label = document
            .objects
            .iter()
            .find(|object| object.stable_id.ends_with("legend-label-0"))
            .unwrap();

        assert!(
            (key.bounds.y + key.bounds.height / 2.0
                - label.bounds.y
                - label.bounds.height / 2.0
                - 1.7)
                .abs()
                < 0.01
        );
        assert!(matches!(
            &label.visual,
            Visual::TextLayout { visual, .. } if matches!(visual.as_ref(), Visual::RichText { runs, .. } if runs[0].color == 0x0000_00ff)
        ));
    }

    #[test]
    fn footnote_charts_reuse_sparse_shared_scatter_semantics() {
        let document_xml = br#"<w:document xmlns:w="w" xmlns:r="r"><w:body>
          <w:p><w:r><w:t>Body</w:t><w:footnoteReference w:id="3"/></w:r></w:p>
          <w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="720" w:right="720" w:bottom="720" w:left="720"/></w:sectPr>
        </w:body></w:document>"#;
        let document_relationships = br#"<Relationships>
          <Relationship Id="rIdFootnotes" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footnotes" Target="footnotes.xml"/>
        </Relationships>"#;
        let footnotes = br#"<w:footnotes xmlns:w="w" xmlns:r="r" xmlns:wp="wp" xmlns:a="a" xmlns:c="c">
          <w:footnote w:id="3"><w:p><w:r><w:footnoteRef/><w:drawing><wp:inline><wp:extent cx="3810000" cy="1905000"/><a:graphic><a:graphicData><c:chart r:id="rIdChart"/></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p></w:footnote>
        </w:footnotes>"#;
        let footnote_relationships = br#"<Relationships>
          <Relationship Id="rIdChart" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/chart" Target="charts/chart1.xml"/>
        </Relationships>"#;
        let chart = br#"<c:chartSpace xmlns:c="c" xmlns:a="a"><c:chart><c:plotArea><c:scatterChart><c:scatterStyle val="lineMarker"/>
          <c:ser><c:xVal><c:strLit><c:pt idx="0"><c:v>A</c:v></c:pt><c:pt idx="1"><c:v>B</c:v></c:pt><c:pt idx="2"><c:v>C</c:v></c:pt></c:strLit></c:xVal><c:yVal><c:numLit><c:pt idx="0"><c:v>4</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt><c:pt idx="2"><c:v>3</c:v></c:pt></c:numLit></c:yVal></c:ser>
          <c:ser><c:spPr><a:ln><a:noFill/></a:ln></c:spPr><c:marker><c:symbol val="circle"/></c:marker><c:xVal><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="2"><c:v>3</c:v></c:pt></c:numLit></c:xVal><c:yVal><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>8</c:v></c:pt><c:pt idx="2"><c:v>5</c:v></c:pt></c:numLit></c:yVal></c:ser>
        </c:scatterChart></c:plotArea></c:chart></c:chartSpace>"#;
        let bytes = stored_zip(&[
            (PART, document_xml),
            ("word/_rels/document.xml.rels", document_relationships),
            ("word/footnotes.xml", footnotes),
            ("word/_rels/footnotes.xml.rels", footnote_relationships),
            ("word/charts/chart1.xml", chart),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let chart_objects = document
            .objects
            .iter()
            .filter(|object| object.source.part == "word/charts/chart1.xml")
            .collect::<Vec<_>>();

        assert_eq!(
            chart_objects
                .iter()
                .filter(|object| object.stable_id.contains("scatter-marker"))
                .count(),
            5
        );
        assert_eq!(
            chart_objects
                .iter()
                .filter(|object| object.stable_id.contains("scatter-line"))
                .map(|object| match &object.visual {
                    Visual::PaintedShape {
                        geometry: Geometry::Path { commands, .. },
                        ..
                    } => commands
                        .iter()
                        .filter(|command| matches!(command, PathCommand::LineTo { .. }))
                        .count(),
                    _ => 0,
                })
                .sum::<usize>(),
            2
        );
    }

    #[test]
    fn vml_rectangle_explicit_paint_overrides_defaults() {
        let xml = br##"<w:document xmlns:w="w" xmlns:v="urn:schemas-microsoft-com:vml"><w:body>
          <w:p><w:r><w:pict><v:rect style="width:18pt;height:15.6pt" filled="f" stroked="f"/></w:pict></w:r></w:p>
          <w:p><w:r><w:pict><v:rect style="width:18pt;height:15.6pt" fillcolor="#ff0000" strokecolor="#0000ff"/></w:pict></w:r></w:p>
          <w:sectPr/>
        </w:body></w:document>"##;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        for (index, fill, stroke) in [
            (0, Paint::None, Paint::None),
            (1, Paint::Solid(0xff00_00ff), Paint::Solid(0x0000_ffff)),
        ] {
            let Block::Paragraph(paragraph) = &parsed.blocks[index] else {
                panic!("VML rectangle paragraph expected");
            };
            let drawing = &paragraph.drawings[0];
            assert_eq!(drawing.shape_fill, fill);
            assert_eq!(drawing.shape_stroke, stroke);
            if index == 0 {
                assert_eq!(drawing.shape_stroke_width, 0.0);
            }
        }
    }

