    #[test]
    fn fits_and_centers_page_relative_vml_text_boxes() {
        let xml = br#"<w:document xmlns:w="w" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:w10="urn:schemas-microsoft-com:office:word"><w:body>
          <w:p><w:r><w:t>Body below box</w:t><w:pict><v:rect style="position:absolute;width:532pt;height:20pt;z-index:100;mso-position-horizontal:center;mso-position-horizontal-relative:page;mso-wrap-distance-bottom:10pt"><v:textbox style="mso-fit-shape-to-text:t" inset="36pt,0,10.8pt,0"><w:txbxContent>
            <w:p><w:pPr><w:spacing w:before="200" w:after="200"/></w:pPr><w:r><w:t>This text must wrap onto several lines inside the fitted legacy text box.</w:t></w:r></w:p>
            <w:p><w:pPr><w:spacing w:before="200" w:after="200"/></w:pPr><w:r><w:t>The second paragraph must remain visible.</w:t></w:r></w:p>
          </w:txbxContent></v:textbox><w10:wrap type="square" anchorx="page" anchory="page"/></v:rect></w:pict></w:r></w:p>
          <w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1800" w:right="1800" w:bottom="1800" w:left="1800"/></w:sectPr>
        </w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let drawing = document
            .objects
            .iter()
            .find(|object| object.stable_id.starts_with("docx:drawing:"))
            .expect("VML text box is rendered");
        let first_paragraph = document
            .objects
            .iter()
            .find(|object| {
                object.stable_id.contains(":paragraph:")
                    && object
                        .text
                        .as_deref()
                        .is_some_and(|text| text.starts_with("This text"))
            })
            .expect("first text-box paragraph is rendered");
        let body = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("Body below box"))
            .expect("wrapped body paragraph is rendered");
        let second_paragraph = document
            .objects
            .iter()
            .find(|object| {
                object.text.as_deref() == Some("The second paragraph must remain visible.")
            })
            .expect("second text-box paragraph is rendered");

        assert!((drawing.bounds.width - 532.0 * POINTS_TO_CSS_PIXELS).abs() < 0.01);
        assert!((drawing.bounds.x - (816.0 - drawing.bounds.width) / 2.0).abs() < 0.01);
        assert!(drawing.bounds.height > 20.0 * POINTS_TO_CSS_PIXELS);
        assert!(first_paragraph.z > drawing.z);
        assert!(
            (second_paragraph.bounds.y
                - first_paragraph.bounds.y
                - first_paragraph.bounds.height
                - 200.0 / TWIPS_PER_CSS_PIXEL)
                .abs()
                < 0.01
        );
        assert!(body.bounds.y >= drawing.bounds.y + drawing.bounds.height + 13.3);
        assert!(
            (first_paragraph.bounds.x - drawing.bounds.x - 48.0).abs() < 0.01,
            "drawing x={} paragraph x={}",
            drawing.bounds.x,
            first_paragraph.bounds.x
        );
        assert!(document.objects.iter().any(|object| {
            object.text.as_deref() == Some("The second paragraph must remain visible.")
        }));
    }

