    #[test]
    fn preserves_original_picture_watermark_scale_and_washout() {
        for (bytes, width, height, washout) in [
            (
                include_bytes!("../../tests/fixtures/picture-watermark-auto.docx").as_slice(),
                431.6 * 4.0 / 3.0,
                431.6,
                true,
            ),
            (
                include_bytes!("../../tests/fixtures/picture-watermark-50.docx").as_slice(),
                512.0,
                384.0,
                false,
            ),
            (
                include_bytes!("../../tests/fixtures/picture-watermark-150.docx").as_slice(),
                1536.0,
                1152.0,
                true,
            ),
        ] {
            let package = Package::open(bytes, Limits::default()).unwrap();
            let document = parse(&package, PART, Vec::new()).unwrap();
            let watermark = document
                .objects
                .iter()
                .find(|object| {
                    object.source.part == "word/header2.xml" && object.kind == ObjectKind::Image
                })
                .expect("original watermark image");
            assert!(
                (watermark.bounds.width - width).abs() < 0.01,
                "{:?}",
                watermark.bounds
            );
            assert!((watermark.bounds.height - height).abs() < 0.01);
            let page = &document.units[0];
            assert!((watermark.bounds.x + width / 2.0 - page.width / 2.0).abs() < 0.01);
            assert!((watermark.bounds.y + height / 2.0 - page.height / 2.0).abs() < 0.01);
            match &watermark.visual {
                Visual::ImageAdjustment { adjustment, visual } if washout => {
                    assert!((adjustment.contrast + 0.7).abs() < 0.0001);
                    assert!((adjustment.brightness - 0.7).abs() < 0.0001);
                    assert!(matches!(visual.as_ref(), Visual::Image { .. }));
                }
                Visual::Image { .. } if !washout => {}
                visual => panic!(
                    "incorrect washout={washout}: {:?}",
                    std::mem::discriminant(visual)
                ),
            }
        }
    }

