    #[test]
    fn drop_cap_margin_short_body_and_orphan_keep_all_text() {
        for location in ["drop", "margin"] {
            let xml = format!(
                r#"<w:document xmlns:w="w"><w:body>
              <w:p><w:pPr><w:framePr w:dropCap="{location}" w:lines="3" w:hSpace="60"/></w:pPr><w:r><w:rPr><w:sz w:val="72"/></w:rPr><w:t>T</w:t></w:r></w:p>
              <w:p><w:r><w:t>iny.</w:t></w:r></w:p>
              <w:p><w:r><w:t>Following</w:t></w:r></w:p>
              <w:p><w:pPr><w:framePr w:dropCap="drop" w:lines="3"/></w:pPr><w:r><w:t>Orphan</w:t></w:r></w:p>
              <w:sectPr/></w:body></w:document>"#
            );
            let document = layout_document(
                parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new()).unwrap(),
                Limits::default(),
                PART,
            )
            .unwrap();
            let find = |text| {
                document
                    .objects
                    .iter()
                    .find(|o| o.text.as_deref() == Some(text))
                    .unwrap()
            };
            let cap = find("T");
            let body = find("iny.");
            assert!((body.bounds.y - cap.bounds.y).abs() < 0.01);
            assert!(find("Following").bounds.y >= cap.bounds.y + cap.bounds.height);
            assert_eq!(find("Following").bounds.x, 96.0);
            if location == "margin" {
                assert_eq!(body.bounds.x, 96.0);
                assert!(cap.bounds.x < 96.0);
            } else {
                assert!(body.bounds.x > 96.0);
            }
            find("Orphan");
        }
    }

