    #[test]
    fn wordprocessing_groups_reuse_drawingml_picture_geometry() {
        let source = Package::open(
            include_bytes!("../../tests/fixtures/report-drop-cap.docx"),
            Limits::default(),
        )
        .unwrap();
        let xml = String::from_utf8(source.required_part(PART).unwrap().into_vec()).unwrap();
        let mut results = Vec::new();
        for document_xml in [
            xml.clone(),
            xml.replace("wpg:wgp", "p:grpSp").replace("wps:wsp", "p:sp"),
        ] {
            let bytes = stored_zip(&[
                (PART, document_xml.as_bytes()),
                (
                    "word/_rels/document.xml.rels",
                    &source
                        .required_part("word/_rels/document.xml.rels")
                        .unwrap(),
                ),
                (
                    "word/theme/theme1.xml",
                    &source.required_part("word/theme/theme1.xml").unwrap(),
                ),
                (
                    "word/media/image1.jpeg",
                    &source.required_part("word/media/image1.jpeg").unwrap(),
                ),
            ]);
            let package = Package::open(&bytes, Limits::default()).unwrap();
            let (groups, _) =
                super::parse_ooxml_locked_canvases(&package, PART, &FontMetricTable::default())
                    .unwrap();
            assert_eq!(groups.len(), 1);
            let image = groups[0]
                .iter()
                .find(|o| o.kind == ObjectKind::Image)
                .unwrap();
            results.push((image.bounds, image.visual.clone()));
        }
        assert_eq!(results[0], results[1]);
    }

