    #[test]
    fn word_settings_enable_shared_punctuation_fitting_without_changing_disabled_layout() {
        let text = "中去除个人信息的行为，使其保持不可被检索、访问的状态。";
        let xml = format!(
            r#"<w:document xmlns:w="w"><w:body><w:p>
          <w:pPr><w:jc w:val="both"/><w:spacing w:line="624" w:lineRule="exact" w:after="0"/></w:pPr>
          <w:r><w:rPr><w:rFonts w:ascii="FangSong" w:eastAsia="FangSong"/><w:sz w:val="32"/></w:rPr><w:t>{text}</w:t></w:r>
          </w:p><w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1440" w:bottom="1440" w:left="1800" w:right="1800"/></w:sectPr>
          </w:body></w:document>"#
        );
        let relationships = br#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
          <Relationship Id="settings" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings" Target="settings.xml"/>
          </Relationships>"#;
        for (setting, lines) in [("compressPunctuation", 1.0), ("doNotCompress", 2.0)] {
            let settings = format!(
                r#"<w:settings xmlns:w="w"><w:characterSpacingControl w:val="{setting}"/></w:settings>"#
            );
            let bytes = stored_zip(&[
                (PART, xml.as_bytes()),
                ("word/_rels/document.xml.rels", relationships),
                ("word/settings.xml", settings.as_bytes()),
            ]);
            let package = Package::open(&bytes, Limits::default()).unwrap();
            let document = parse(&package, PART, Vec::new()).unwrap();
            let object = document
                .objects
                .iter()
                .find(|o| o.text.as_deref() == Some(text))
                .unwrap();
            assert!(
                (object.bounds.height - 41.6 * lines).abs() < 0.01,
                "{setting}: {:?}",
                object.bounds
            );
            let Visual::TextLayout { layout, .. } = &object.visual else {
                panic!("text layout")
            };
            assert_eq!(layout.compress_punctuation, lines == 1.0);
        }
    }

    #[test]
    fn applies_document_default_tabs_and_dynamic_centered_page_fields() {
        let document_xml = br#"<w:document xmlns:w="w" xmlns:r="r"><w:body>
          <w:p><w:r><w:t>A</w:t></w:r><w:r><w:tab/></w:r><w:r><w:t>B</w:t></w:r>
            <w:r><w:br w:type="page"/></w:r><w:r><w:t>C</w:t></w:r></w:p>
          <w:sectPr><w:footerReference w:type="default" r:id="rIdFooter"/>
            <w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440" w:footer="720"/>
          </w:sectPr>
        </w:body></w:document>"#;
        let relationships = br#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
          <Relationship Id="rIdFooter" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" Target="footer1.xml"/>
          <Relationship Id="rIdSettings" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings" Target="settings.xml"/>
        </Relationships>"#;
        let settings = br#"<w:settings xmlns:w="w"><w:uiCompat97To2003/><w:defaultTabStop w:val="420"/></w:settings>"#;
        let footer = br#"<w:ftr xmlns:w="w"><w:p><w:pPr><w:framePr w:hAnchor="margin" w:xAlign="center"/></w:pPr><w:r><w:t>Page </w:t></w:r>
          <w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText> PAGE </w:instrText></w:r>
          <w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>1</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r><w:r><w:t> of report</w:t></w:r>
        </w:p></w:ftr>"#;
        let bytes = stored_zip(&[
            (PART, document_xml),
            ("word/_rels/document.xml.rels", relationships),
            ("word/settings.xml", settings),
            ("word/footer1.xml", footer),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let body = document
            .objects
            .iter()
            .find(|object| object.source.part == PART && object.text.as_deref() == Some("A\tB"))
            .expect("first body fragment is rendered");
        let Visual::TextLayout { layout, visual } = &body.visual else {
            panic!("tabbed paragraph must expose text layout");
        };
        let Visual::RichText { runs, .. } = visual.as_ref() else {
            panic!("tabbed paragraph must expose rich text");
        };
        let footers = document
            .objects
            .iter()
            .filter(|object| object.source.part == "word/footer1.xml")
            .collect::<Vec<_>>();

        assert_eq!(layout.default_tab_stop, 28.0);
        assert_eq!(runs[0].font_size, DEFAULT_FONT_SIZE);
        assert_eq!(footers.len(), 2);
        assert_eq!(footers[0].text.as_deref(), Some("Page 1 of report"));
        assert_eq!(footers[1].text.as_deref(), Some("Page 2 of report"));
        for footer in footers {
            let visual = match &footer.visual {
                Visual::TextLayout { visual, .. } => visual.as_ref(),
                visual => visual,
            };
            let Visual::RichText { align, .. } = visual else {
                panic!("footer must use rich text");
            };
            assert_eq!(*align, TextAlign::Center);
        }
    }

