    #[test]
    fn complex2005_smartart_preserves_target_list_geometry() {
        let bytes = include_bytes!("../../tests/fixtures/complex2005_12rtm.docx");
        let package = Package::open(bytes, Limits::default()).unwrap();
        let document = super::parse(&package, PART, Vec::new()).unwrap();
        let title = document
            .objects
            .iter()
            .find(|o| o.text.as_deref() == Some("SMART ART!"))
            .unwrap();
        let typical = document
            .objects
            .iter()
            .find(|o| o.text.as_deref() == Some("Typical Doc"))
            .unwrap();
        let complex = document
            .objects
            .iter()
            .find(|o| o.text.as_deref() == Some("Complex Doc"))
            .unwrap();
        let circles = document
            .objects
            .iter()
            .filter(|o| {
                o.unit_index == title.unit_index
                    && matches!(
                        o.visual,
                        Visual::PaintedShape {
                            geometry: Geometry::Ellipse,
                            ..
                        }
                    )
            })
            .collect::<Vec<_>>();
        assert_eq!(
            circles.len(),
            3,
            "target3 must retain its three nested circles"
        );
        assert!(
            circles.iter().all(|circle| matches!(
                circle.visual,
                Visual::PaintedShape {
                    fill: Paint::Solid(0x4f81_bdff),
                    ..
                }
            )),
            "diagram must use the DOCX accent1, not the PowerPoint default"
        );
        assert!(title.bounds.y < typical.bounds.y && typical.bounds.y < complex.bounds.y);
        assert!(
            circles[0].bounds.width > circles[1].bounds.width
                && circles[1].bounds.width > circles[2].bounds.width
        );
        let details = document
            .objects
            .iter()
            .find(|o| {
                o.text
                    .as_deref()
                    .is_some_and(|text| text.contains("5 pages"))
                    && o.parent_numeric_id == typical.parent_numeric_id
            })
            .unwrap();
        assert!(details.bounds.x > typical.bounds.x + typical.bounds.width - 0.01);
        assert!(details.bounds.y + details.bounds.height <= complex.bounds.y + 0.01);
    }

    #[test]
    fn complex0_inline_controls_reserve_width_and_hide_form_markers() {
        let package = Package::open(
            include_bytes!("../../tests/fixtures/complex0.docx"),
            Limits::default(),
        )
        .unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        for index in [669, 671] {
            let objects = document.objects.iter().filter(|object| matches!(object.source.locator, SourceLocator::Docx { paragraph_index: Some(value), .. } if value == index)).collect::<Vec<_>>();
            let text = objects
                .iter()
                .find(|object| object.text.as_deref().is_some_and(|text| !text.is_empty()))
                .unwrap();
            let image = objects
                .iter()
                .find(|object| object.kind == ObjectKind::Image)
                .unwrap();
            let Visual::TextLayout { layout, .. } = &text.visual else {
                panic!("control caption layout");
            };
            assert!(
                text.bounds.x + layout.first_line_indent
                    >= image.bounds.x + image.bounds.width - 0.01,
                "inline control {index} overlaps its caption"
            );
        }
        assert!(!document.objects.iter().any(|object| matches!(
            object.text.as_deref(),
            Some("Top of Form" | "Bottom of Form")
        )));
    }

