    #[test]
    fn complex2005_cover_submission_keeps_three_lines() {
        let bytes = include_bytes!("../../tests/fixtures/complex2005_12rtm.docx");
        let package = Package::open(bytes, Limits::default()).unwrap();
        // Cambria-compatible Caladea 1.002 advances, checked against Word PDF output.
        // Pin metrics so this real-file regression also runs without local fonts.
        let chars = " -ACDEFIMPRSTabcdefghilmnopqrstuvwy";
        let advances = [
            0.22, 0.332, 0.623, 0.562, 0.662, 0.575, 0.537, 0.324, 0.815, 0.568, 0.621, 0.496,
            0.593, 0.488, 0.547, 0.441, 0.555, 0.488, 0.303, 0.494, 0.552, 0.278, 0.271, 0.832,
            0.558, 0.531, 0.556, 0.547, 0.414, 0.43, 0.338, 0.552, 0.504, 0.774, 0.504,
        ];
        assert_eq!(chars.chars().count(), advances.len());
        let metrics = font_metrics("Cambria", &chars.chars().zip(advances).collect::<Vec<_>>());
        let document =
            super::parse_with_font_metrics(&package, PART, Vec::new(), &metrics).unwrap();
        let paragraph = document
            .objects
            .iter()
            .find(|object| {
                object
                    .text
                    .as_deref()
                    .is_some_and(|text| text.starts_with("Submitted to the Department"))
            })
            .unwrap();
        let Visual::RichText {
            runs, line_height, ..
        } = rich_text_visual(&paragraph.visual)
        else {
            panic!("submission paragraph must retain its real text");
        };
        assert_eq!(runs[0].font_family, "Cambria");
        assert!((runs[0].font_size - 40.0 / 3.0).abs() < 0.001);
        assert_eq!((paragraph.bounds.height / line_height).round() as usize, 3);
        assert!((paragraph.bounds.width - (7096.0 - 230.0) / 15.0).abs() < 0.01);
        let title = document
            .objects
            .iter()
            .find(|o| {
                o.text
                    .as_deref()
                    .is_some_and(|t| t.starts_with("Development of Interactive"))
            })
            .unwrap();
        let Visual::RichText {
            line_height: title_line_height,
            ..
        } = rich_text_visual(&title.visual)
        else {
            panic!("missing title");
        };
        assert_eq!(
            (title.bounds.height / title_line_height).round() as usize,
            7
        );
        let cell = &document.objects[paragraph.parent_numeric_id.unwrap() as usize];
        assert!((paragraph.bounds.x - cell.bounds.x - 115.0 / 15.0).abs() < 0.01);
        assert!((paragraph.bounds.y - cell.bounds.y - 216.0 / 15.0).abs() < 0.01);
    }

    #[test]
    fn cell_margin_overrides_survive_row_splitting_and_repeated_headers() {
        let text = "Body ".repeat(32);
        let xml = format!(
            r#"<w:document xmlns:w="w"><w:body><w:tbl>
            <w:tblPr><w:tblW w:w="2400" w:type="dxa"/><w:tblLayout w:type="fixed"/></w:tblPr>
            <w:tblGrid><w:gridCol w:w="2400"/></w:tblGrid>
            <w:tr><w:trPr><w:tblHeader/></w:trPr><w:tc><w:p><w:r><w:t>Header</w:t></w:r></w:p></w:tc></w:tr>
            <w:tr><w:tc><w:tcPr><w:tcMar><w:top w:w="300"/><w:bottom w:w="450"/>
            <w:left w:w="150"/><w:right w:w="300"/></w:tcMar></w:tcPr>
            <w:p><w:r><w:t>{text}</w:t></w:r></w:p></w:tc></w:tr></w:tbl>
            <w:sectPr><w:pgSz w:w="4500" w:h="3000"/><w:pgMar w:top="150" w:left="150" w:right="150" w:bottom="150"/></w:sectPr>
            </w:body></w:document>"#
        );
        let parsed =
            parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        assert!(document.units.len() > 1);
        let mut words = 0;
        for object in &document.objects {
            if let Some(text) = object.text.as_deref().filter(|text| text.contains("Body")) {
                words += text.split_whitespace().count();
                let cell = &document.objects[object.parent_numeric_id.unwrap() as usize];
                assert!((object.bounds.x - cell.bounds.x - 10.0).abs() < 0.01);
                assert!((object.bounds.width - (160.0 - 30.0)).abs() < 0.01);
                assert!(object.bounds.y >= cell.bounds.y - 0.01);
                assert!(
                    object.bounds.y + object.bounds.height
                        <= cell.bounds.y + cell.bounds.height + 0.01
                );
            }
        }
        assert_eq!(words, 32);
        assert_eq!(
            document
                .objects
                .iter()
                .filter(|o| o.text.as_deref() == Some("Header"))
                .count(),
            document.units.len()
        );
    }

