    #[test]
    fn browser_font_metrics_change_docx_line_wrapping() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:r><w:rPr><w:rFonts w:ascii="P0 Sans"/></w:rPr><w:t>WWWWWWWW</w:t></w:r></w:p>
          <w:sectPr><w:pgSz w:w="1500" w:h="3000"/><w:pgMar w:top="150" w:right="150" w:bottom="150" w:left="150"/></w:sectPr>
        </w:body></w:document>"#;
        let approximate = layout_document(
            parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap(),
            Limits::default(),
            PART,
        )
        .unwrap();
        let metrics = single_font_metric("P0 Sans", 'W', 1.0);
        let measured = layout_document_with_font_metrics(
            parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap(),
            Limits::default(),
            PART,
            &metrics,
        )
        .unwrap();

        assert_eq!(approximate.objects[0].text.as_deref(), Some("WWWWWWWW"));
        assert_eq!(measured.objects[0].text.as_deref(), Some("WWWWWWWW"));
        assert!(measured.objects[0].bounds.height > approximate.objects[0].bounds.height);
    }

    #[test]
    fn browser_vertical_font_metrics_drive_docx_natural_line_height() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:r><w:rPr><w:rFonts w:ascii="P0 Sans"/><w:sz w:val="20"/></w:rPr><w:t>W</w:t></w:r></w:p>
          <w:p><w:pPr><w:rPr><w:rFonts w:ascii="P0 Sans"/><w:sz w:val="20"/></w:rPr></w:pPr></w:p>
          <w:sectPr><w:pgSz w:w="3000" w:h="3000"/><w:pgMar w:top="150" w:right="150" w:bottom="150" w:left="150"/></w:sectPr>
        </w:body></w:document>"#;
        for (measured, expected) in [(1.0, 1.15), (1.6, 1.6)] {
            let metrics = font_metric_with_line_height("P0 Sans", 'W', 0.9, measured, false);
            let document = layout_document_with_font_metrics(
                parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap(),
                Limits::default(),
                PART,
                &metrics,
            )
            .unwrap();
            let line_height = match rich_text_visual(&document.objects[0].visual) {
                Visual::RichText { line_height, .. } => *line_height,
                _ => panic!("paragraph must use rich text"),
            };
            assert!((line_height - 20.0 * POINTS_TO_CSS_PIXELS / 2.0 * expected).abs() < 0.001);
            assert!(
                (document.objects[1].bounds.height - 20.0 * POINTS_TO_CSS_PIXELS / 2.0 * expected)
                    .abs()
                    < 0.001
            );
        }
    }

    #[test]
    fn rotates_east_asian_vertical_runs_left() {
        let xml = br#"<w:document xmlns:w="http://purl.oclc.org/ooxml/wordprocessingml/main"><w:body>
          <w:p><w:r><w:rPr><w:eastAsianLayout w:vert="1"/></w:rPr><w:t>x</w:t></w:r></w:p>
          <w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr>
        </w:body></w:document>"#;
        let document = layout_document(
            parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap(),
            Limits::default(),
            PART,
        )
        .unwrap();
        let Visual::TextLayout { layout, .. } = &document.objects[0].visual else {
            panic!("paragraph must expose text layout");
        };

        assert_eq!(layout.orientation, TextOrientation::Rotated270);
    }

