    #[test]
    fn automatic_mixed_size_lines_use_their_own_natural_heights() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:pPr><w:rPr><w:sz w:val="48"/></w:rPr></w:pPr>
            <w:r><w:rPr><w:sz w:val="16"/></w:rPr><w:t xml:space="preserve">small small </w:t></w:r>
            <w:r><w:rPr><w:sz w:val="24"/></w:rPr><w:t xml:space="preserve">medium medium </w:t></w:r>
            <w:r><w:rPr><w:sz w:val="48"/></w:rPr><w:t>LARGE</w:t></w:r>
          </w:p><w:sectPr><w:pgSz w:w="1500" w:h="6000"/><w:pgMar w:top="150" w:right="150" w:bottom="150" w:left="150"/></w:sectPr>
        </w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let lines = document
            .objects
            .iter()
            .filter(|object| object.stable_id.starts_with("docx:paragraph:0:fragment:"))
            .collect::<Vec<_>>();

        assert!(lines.len() >= 3);
        let minimum = lines
            .iter()
            .map(|line| line.bounds.height)
            .fold(f32::INFINITY, f32::min);
        let maximum = lines
            .iter()
            .map(|line| line.bounds.height)
            .fold(0.0_f32, f32::max);
        assert!(minimum < maximum);
        assert!(
            lines.iter().map(|line| line.bounds.height).sum::<f32>() < lines.len() as f32 * maximum
        );
    }

