    #[test]
    fn eq_parentheses_stretch_around_arrays_without_resizing_the_cells() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r>
          <w:r><w:instrText>eq \b(\a(1,2))</w:instrText></w:r>
          <w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>
          <w:sectPr/>
        </w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let equation = document
            .objects
            .iter()
            .find(|o| o.text.as_deref() == Some("(1\n2)"))
            .unwrap();
        let parts = document
            .objects
            .iter()
            .filter(|o| o.parent_numeric_id == Some(equation.numeric_id))
            .collect::<Vec<_>>();
        assert_eq!(parts.len(), 4);
        assert!((parts[0].bounds.height - equation.bounds.height).abs() < 0.01);
        assert!((parts[3].bounds.height - equation.bounds.height).abs() < 0.01);
        assert!((parts[1].bounds.height * 2.0 - equation.bounds.height).abs() < 0.01);
        let single = super::EquationNode::Parentheses(Box::new(super::EquationNode::Text {
            text: "a".to_owned(),
            baseline_shift: 0.0,
        }))
        .layout(&super::TextStyle::default(), &FontMetricTable::default());
        assert_eq!(single.children.len(), 3);
        assert!(
            single
                .children
                .iter()
                .all(|child| matches!(child.visual, Visual::TextLayout { .. }))
        );
    }

    #[test]
    fn eq_radicals_stretch_for_stacked_contents_and_keep_the_degree_clear() {
        use super::{EquationNode, TextStyle};
        let text = |value: &str| EquationNode::Text {
            text: value.to_owned(),
            baseline_shift: 0.0,
        };
        let style = TextStyle::default();
        let metrics = FontMetricTable::default();
        let simple = EquationNode::Radical {
            degree: None,
            radicand: Box::new(text("a")),
        }
        .layout(&style, &metrics);
        let stacked = EquationNode::Radical {
            degree: Some(Box::new(text("-3"))),
            radicand: Box::new(EquationNode::Fraction(
                Box::new(text("a")),
                Box::new(text("b")),
            )),
        }
        .layout(&style, &metrics);
        assert!(stacked.height > simple.height);
        for layout in [&simple, &stacked] {
            let hook = &layout.children[0];
            let Visual::PaintedShape {
                geometry: Geometry::Path { commands, .. },
                ..
            } = &hook.visual
            else {
                panic!("scalable radical path")
            };
            let PathCommand::LineTo { y: bottom, .. } = commands[2] else {
                panic!("hook")
            };
            assert!((bottom - (layout.height - style.font_size * 0.25)).abs() < 0.001);
            assert!(layout.children.iter().all(|child| child.bounds.is_valid()));
        }
        let degree = stacked.children.last().unwrap();
        assert!(degree.bounds.x + degree.bounds.width <= stacked.children[0].bounds.x);
    }

