    #[test]
    fn preserves_rich_run_formatting_in_the_display_list() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:pPr><w:jc w:val="right"/><w:spacing w:line="300"/></w:pPr>
            <w:r><w:rPr><w:rFonts w:ascii="Aptos"/><w:sz w:val="28"/><w:w w:val="33"/><w:color w:val="123456"/><w:b/><w:i/><w:u w:val="single"/><w:strike/><w:highlight w:val="yellow"/><w:vertAlign w:val="superscript"/></w:rPr><w:t>Rich</w:t></w:r>
            <w:r><w:rPr><w:rFonts w:ascii="Courier New"/><w:spacing w:val="20"/></w:rPr><w:t> text</w:t></w:r>
          </w:p><w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr>
        </w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let Visual::TextLayout { visual, .. } = &document.objects[0].visual else {
            panic!("paragraph must expose zero-inset text layout");
        };
        let Visual::RichText {
            align,
            line_height,
            runs,
            ..
        } = visual.as_ref()
        else {
            panic!("paragraph must use rich text");
        };
        assert_eq!(*align, TextAlign::End);
        assert_eq!(*line_height, 20.0);
        assert_eq!(runs.len(), 2);
        assert_eq!(runs[0].font_family, "Aptos");
        assert_eq!(runs[0].horizontal_scale, 0.33);
        assert_eq!(runs[0].color, 0x1234_56ff);
        assert!(runs[0].bold && runs[0].italic && runs[0].underline);
        assert!(runs[0].strikethrough);
        assert_eq!(runs[0].highlight, 0xffff_00ff);
        assert!(runs[0].baseline_shift > 0.0);
        assert_eq!(runs[1].font_family, "Courier New");
        assert!(runs[1].letter_spacing > 1.0);
    }

