    #[test]
    fn applies_inherited_character_style_size_and_position() {
        let document_xml = br#"<w:document xmlns:w="w"><w:body><w:p>
          <w:r><w:t>Base</w:t></w:r>
          <w:r><w:rPr><w:rStyle w:val="subscript"/></w:rPr><w:t>Subscript</w:t></w:r>
        </w:p><w:sectPr/></w:body></w:document>"#;
        let relationships = br#"<Relationships>
          <Relationship Id="rIdStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
        </Relationships>"#;
        let styles = br#"<w:styles xmlns:w="w">
          <w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:rPr><w:sz w:val="24"/></w:rPr></w:style>
          <w:style w:type="character" w:styleId="DefaultParagraphFont"/>
          <w:style w:type="character" w:styleId="CharSize48"><w:basedOn w:val="DefaultParagraphFont"/><w:rPr><w:position w:val="0"/><w:sz w:val="96"/></w:rPr></w:style>
          <w:style w:type="character" w:styleId="subscript"><w:basedOn w:val="CharSize48"/><w:rPr><w:position w:val="-24"/></w:rPr></w:style>
        </w:styles>"#;
        let bytes = stored_zip(&[
            (PART, document_xml),
            ("word/_rels/document.xml.rels", relationships),
            ("word/styles.xml", styles),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let Visual::RichText { runs, .. } = rich_text_visual(&document.objects[0].visual) else {
            panic!("paragraph must use rich text");
        };

        assert_eq!(runs.len(), 2);
        assert_eq!(runs[0].font_size, 12.0 * POINTS_TO_CSS_PIXELS);
        assert_eq!(runs[1].font_size, 48.0 * POINTS_TO_CSS_PIXELS);
        assert_eq!(runs[1].baseline_shift, -12.0 * POINTS_TO_CSS_PIXELS);
    }

