    #[test]
    fn preserves_docx_symbol_runs_in_body_and_stories() {
        let content = r#"<w:p><w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="28"/><w:b/></w:rPr>
          <w:t>A</w:t><w:sym w:font="Symbol" w:char="F0B7"/><w:t>B</w:t></w:r>
          <w:r><w:rPr><w:rFonts w:ascii="Symbol"/></w:rPr><w:t>&#xF0B7;</w:t></w:r></w:p>"#;
        let xml = format!(r#"<w:document xmlns:w="w"><w:body>{content}</w:body></w:document>"#);
        let parsed =
            parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let Visual::RichText { runs, .. } = rich_text_visual(&document.objects[0].visual) else {
            panic!("symbol paragraph must contain rich text");
        };
        assert_eq!(document.objects[0].text.as_deref(), Some("A•B•"));
        assert_eq!(
            runs.iter()
                .map(|r| (r.text.as_str(), r.font_family.as_str()))
                .collect::<Vec<_>>(),
            [
                ("A", "Arial"),
                ("\u{f0b7}", "Symbol"),
                ("B", "Arial"),
                ("\u{f0b7}", "Symbol")
            ]
        );
        assert_eq!(runs[1].font_size, 14.0 * POINTS_TO_CSS_PIXELS);
        assert!(runs[1].bold);
        for kind in ["footnote", "endnote", "comment"] {
            let xml = format!(
                r#"<w:notes xmlns:w="w"><w:{kind} w:id="2">{content}</w:{kind}></w:notes>"#
            );
            let stories = parse_story_collection_xml(
                xml.as_bytes(),
                Limits::default(),
                "word/notes.xml",
                kind,
            )
            .unwrap();
            let paragraph = &stories[&2].paragraphs[0];
            assert_eq!(paragraph.text, "A•B•", "{kind}");
            assert_eq!(
                paragraph
                    .runs
                    .iter()
                    .map(|r| (r.text.as_str(), r.style.font_family.as_str()))
                    .collect::<Vec<_>>(),
                [
                    ("A", "Arial"),
                    ("\u{f0b7}", "Symbol"),
                    ("B", "Arial"),
                    ("\u{f0b7}", "Symbol")
                ],
                "{kind}"
            );
            assert_eq!(
                paragraph.runs[1].style.font_size,
                14.0 * POINTS_TO_CSS_PIXELS
            );
            assert!(paragraph.runs[1].style.bold);
        }
    }

