    #[test]
    fn contextual_spacing_suppresses_space_only_between_same_style_paragraphs() {
        let theme = super::DocxTheme::default();
        let styles = super::parse_styles_xml(
            br#"<w:styles xmlns:w="w"><w:docDefaults><w:pPrDefault><w:pPr><w:spacing w:after="160"/></w:pPr></w:pPrDefault></w:docDefaults><w:style w:type="paragraph" w:styleId="ListParagraph"><w:pPr><w:contextualSpacing/></w:pPr></w:style></w:styles>"#,
            Limits::default(),
            "word/styles.xml",
            &theme,
        )
        .unwrap();
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:pPr><w:pStyle w:val="ListParagraph"/></w:pPr><w:r><w:t>First</w:t></w:r></w:p>
          <w:p><w:pPr><w:pStyle w:val="ListParagraph"/></w:pPr><w:r><w:t>Second</w:t></w:r></w:p>
          <w:p><w:r><w:t>Third</w:t></w:r></w:p>
          <w:sectPr/>
        </w:body></w:document>"#;
        let parsed = super::parse_document_xml_with_styles(
            xml,
            Limits::default(),
            PART,
            Vec::new(),
            &styles,
            &theme,
        )
        .unwrap();
        for block in &parsed.blocks[..2] {
            let Block::Paragraph(paragraph) = block else {
                panic!("paragraph expected")
            };
            assert_eq!(paragraph.style_id.as_deref(), Some("ListParagraph"));
            assert!(paragraph.contextual_spacing);
        }
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let paragraph = |text| {
            document
                .objects
                .iter()
                .find(|object| object.text.as_deref() == Some(text))
                .unwrap()
        };
        let first = paragraph("First");
        let second = paragraph("Second");
        let third = paragraph("Third");

        assert!(
            (second.bounds.y - first.bounds.y - first.bounds.height).abs() < 0.001,
            "first={:?} second={:?}",
            first.bounds,
            second.bounds
        );
        assert!(
            (third.bounds.y - second.bounds.y - second.bounds.height - 160.0 / TWIPS_PER_CSS_PIXEL)
                .abs()
                < 0.001
        );
    }

    #[test]
    fn applies_line_unit_and_automatic_paragraph_spacing() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:pPr><w:spacing w:after="0" w:afterLines="100"/></w:pPr><w:r><w:t>Line unit</w:t></w:r></w:p>
          <w:p><w:pPr><w:spacing w:after="1000" w:afterAutospacing="1"/></w:pPr><w:r><w:t>Automatic</w:t></w:r></w:p>
          <w:p><w:pPr><w:spacing w:after="0"/></w:pPr><w:r><w:t>Last</w:t></w:r></w:p>
          <w:sectPr/>
        </w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let paragraph = |text| {
            document
                .objects
                .iter()
                .find(|object| object.text.as_deref() == Some(text))
                .unwrap()
        };
        let first = paragraph("Line unit");
        let second = paragraph("Automatic");
        let third = paragraph("Last");
        let first_gap = second.bounds.y - (first.bounds.y + first.bounds.height);
        let automatic_gap = third.bounds.y - (second.bounds.y + second.bounds.height);

        assert!(
            (first_gap - first.bounds.height).abs() < 0.01,
            "{first_gap}"
        );
        assert!(
            (automatic_gap - 10.0 * POINTS_TO_CSS_PIXELS).abs() < 0.01,
            "{automatic_gap}"
        );
    }

