    #[test]
    fn keep_next_reserves_only_the_widow_controlled_start_of_the_following_paragraph() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:pPr><w:spacing w:before="570" w:line="200" w:lineRule="exact"/></w:pPr>
            <w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t>Filler</w:t><w:br/><w:t>Filler</w:t><w:br/><w:t>Filler</w:t></w:r></w:p>
          <w:p><w:pPr><w:keepNext/><w:keepLines/><w:spacing w:line="200" w:lineRule="exact"/></w:pPr>
            <w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t>Heading</w:t></w:r></w:p>
          <w:p><w:pPr><w:spacing w:line="200" w:lineRule="exact"/></w:pPr>
            <w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t>A</w:t><w:br/><w:t>B</w:t><w:br/><w:t>C</w:t><w:br/><w:t>D</w:t></w:r></w:p>
          <w:sectPr><w:pgSz w:w="1800" w:h="1800"/><w:pgMar w:top="150" w:right="150" w:bottom="150" w:left="150"/></w:sectPr>
        </w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let heading = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("Heading"))
            .expect("heading is rendered");
        let mut following_units = document
            .objects
            .iter()
            .filter(|object| {
                object
                    .text
                    .as_deref()
                    .is_some_and(|text| text.contains('A') || text.contains('D'))
            })
            .map(|object| object.unit_index)
            .collect::<Vec<_>>();
        following_units.sort_unstable();
        following_units.dedup();

        assert_eq!(heading.unit_index, 0);
        assert_eq!(following_units, [0, 1]);
    }

