    #[test]
    fn inherits_table_style_spacing_and_cell_margins_without_inventing_row_height() {
        let rows = (1..=52)
            .map(|row| {
                format!(
                    "<w:tr><w:tc><w:p><w:r><w:rPr><w:rFonts w:ascii=\"Arial\"/></w:rPr><w:t>{row}</w:t></w:r></w:p></w:tc></w:tr>"
                )
            })
            .collect::<String>();
        let document_xml = format!(
            r#"<w:document xmlns:w="w"><w:body>
              <w:tbl><w:tblPr><w:tblStyle w:val="TableGrid"/><w:tblCellMar><w:left w:w="216" w:type="dxa"/></w:tblCellMar></w:tblPr>
                <w:tblGrid><w:gridCol w:w="9072"/></w:tblGrid>{rows}
              </w:tbl>
              <w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1417" w:right="1417" w:bottom="1417" w:left="1417"/></w:sectPr>
            </w:body></w:document>"#
        );
        let relationships = br#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
          <Relationship Id="rIdStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
        </Relationships>"#;
        let styles = br#"<w:styles xmlns:w="w">
          <w:docDefaults><w:pPrDefault><w:pPr><w:spacing w:after="160" w:line="259" w:lineRule="auto"/></w:pPr></w:pPrDefault></w:docDefaults>
          <w:style w:type="table" w:default="1" w:styleId="TableNormal"><w:tblPr><w:tblCellMar>
            <w:top w:w="0" w:type="dxa"/><w:left w:w="108" w:type="dxa"/><w:bottom w:w="0" w:type="dxa"/><w:right w:w="108" w:type="dxa"/>
          </w:tblCellMar></w:tblPr></w:style>
          <w:style w:type="table" w:styleId="TableGrid"><w:basedOn w:val="TableNormal"/><w:pPr><w:spacing w:after="0" w:line="240" w:lineRule="auto"/></w:pPr></w:style>
        </w:styles>"#;
        let bytes = stored_zip(&[
            (PART, document_xml.as_bytes()),
            ("word/_rels/document.xml.rels", relationships),
            ("word/styles.xml", styles),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let metrics = font_metric_with_line_height("Arial", '1', 0.5, 1.0, false);
        let document = parse_with_font_metrics(&package, PART, Vec::new(), &metrics).unwrap();
        let first_cell = document
            .objects
            .iter()
            .find(|object| object.stable_id.contains("table:0:row:0:column:0"))
            .unwrap();
        let first_paragraph = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("1"))
            .unwrap();

        assert_eq!(document.units.len(), 1);
        assert!(first_cell.bounds.height < 20.0);
        assert!(
            (first_paragraph.bounds.x - first_cell.bounds.x - 216.0 / TWIPS_PER_CSS_PIXEL).abs()
                < 0.001
        );
    }

    #[test]
    fn preserves_calendar_comment_table_styles() {
        let bytes = include_bytes!("../../tests/fixtures/word-calendar-comments.docx");
        let package = Package::open(bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        for cell in document
            .objects
            .iter()
            .filter(|object| object.kind == crate::model::ObjectKind::Cell)
        {
            assert!(matches!(
                &cell.visual,
                Visual::PaintedShape {
                    stroke: Paint::None,
                    ..
                }
            ));
        }
        assert!(!document.objects.iter().any(|object| {
            object.stable_id.contains("table:0:row:1:column:0:")
                && object.stable_id.contains(":border:")
        }));
        assert!(document.objects.iter().any(|object| {
            object.stable_id.contains("table:0:row:2:column:0:")
                && object.stable_id.ends_with(":border:right")
        }));
        for text in ["May", "M", "1"] {
            let objects: Vec<_> = document
                .objects
                .iter()
                .filter(|object| {
                    object
                        .text
                        .as_deref()
                        .is_some_and(|value| value.eq_ignore_ascii_case(text))
                })
                .collect();
            assert!(!objects.is_empty(), "missing {text}");
            for object in objects {
                let Visual::RichText { runs, .. } = rich_text_visual(&object.visual) else {
                    panic!("calendar text must use rich text");
                };
                let header = text != "1";
                assert_eq!(
                    runs[0].color,
                    if header { 0x4f81bdff } else { 0x000000ff },
                    "{text}"
                );
                assert_eq!(
                    runs[0].font_family,
                    if header { "Cambria" } else { "Calibri" },
                    "{text}"
                );
                let size = if text == "May" {
                    20.0
                } else if header {
                    16.0
                } else {
                    14.0
                };
                assert!((runs[0].font_size - size * super::POINTS_TO_CSS_PIXELS).abs() < 0.01);
                if text == "May" {
                    assert_eq!(
                        runs.iter().map(|run| run.text.as_str()).collect::<String>(),
                        "MAY"
                    );
                }
            }
        }
    }

    #[test]
    fn conditional_table_styles_merge_without_leaking_into_body() {
        let theme = super::DocxTheme::default();
        let styles = super::parse_styles_xml(br#"<w:styles xmlns:w="w">
          <w:style w:type="table" w:styleId="Base">
            <w:tblStylePr w:type="firstRow"><w:rPr><w:rFonts w:ascii="Cambria"/><w:color w:val="4F81BD"/><w:caps/></w:rPr><w:tcPr><w:shd w:fill="FFFF00"/><w:tcBorders><w:right w:val="nil"/></w:tcBorders></w:tcPr></w:tblStylePr>
          </w:style>
          <w:style w:type="table" w:styleId="Child"><w:basedOn w:val="Base"/>
            <w:tblStylePr w:type="firstRow"><w:rPr><w:sz w:val="32"/></w:rPr></w:tblStylePr>
          </w:style></w:styles>"#, Limits::default(), "word/styles.xml", &theme).unwrap();
        let xml = br#"<w:document xmlns:w="w"><w:body><w:tbl>
          <w:tblPr><w:tblStyle w:val="Child"/><w:tblLook w:firstRow="1"/></w:tblPr>
          <w:tblGrid><w:gridCol w:w="1440"/></w:tblGrid>
          <w:tr><w:tc><w:p><w:r><w:rPr><w:color w:val="FF0000"/><w:caps w:val="0"/></w:rPr><w:t>Header</w:t></w:r></w:p></w:tc></w:tr>
          <w:tr><w:tc><w:p><w:r><w:t>Body</w:t></w:r></w:p></w:tc></w:tr>
          </w:tbl><w:sectPr/></w:body></w:document>"#;
        let parsed = super::parse_document_xml_with_styles(
            xml,
            Limits::default(),
            PART,
            Vec::new(),
            &styles,
            &theme,
        )
        .unwrap();
        let super::Block::Table(table) = &parsed.blocks[0] else {
            panic!("missing table");
        };
        let header = table.rows[0].cells[0].paragraphs().next().unwrap();
        assert_eq!(header.text, "Header");
        assert_eq!(header.runs[0].style.color, 0xff0000ff);
        assert_eq!(header.runs[0].style.font_family, "Cambria");
        assert!((header.runs[0].style.font_size - 16.0 * super::POINTS_TO_CSS_PIXELS).abs() < 0.01);
        assert!(matches!(
            table.rows[0].cells[0].fill,
            Paint::Solid(0xffff00ff)
        ));
        assert_eq!(
            table.rows[0].cells[0].borders.right.unwrap().stroke_width,
            0.0
        );
        let body = table.rows[1].cells[0].paragraphs().next().unwrap();
        assert_eq!(body.text, "Body");
        assert_eq!(body.runs[0].style.color, 0x000000ff);
        assert!(!body.runs[0].style.caps);
    }

    #[test]
    fn applies_conditional_table_style_cell_fills() {
        let document_xml = br#"<w:document xmlns:w="w"><w:body><w:tbl>
          <w:tblPr><w:tblStyle w:val="GridTable4-Accent5"/><w:tblLook w:firstRow="1" w:firstColumn="1" w:noHBand="0" w:noVBand="1"/></w:tblPr>
          <w:tblGrid><w:gridCol w:w="1440"/><w:gridCol w:w="1440"/></w:tblGrid>
          <w:tr><w:tc><w:p><w:r><w:t>H1</w:t></w:r></w:p></w:tc><w:tc><w:p><w:r><w:t>H2</w:t></w:r></w:p></w:tc></w:tr>
          <w:tr><w:tc><w:p><w:r><w:t>A1</w:t></w:r></w:p></w:tc><w:tc><w:p><w:r><w:t>A2</w:t></w:r></w:p></w:tc></w:tr>
        </w:tbl><w:sectPr/></w:body></w:document>"#;
        let relationships = br#"<Relationships><Relationship Id="rIdStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>"#;
        let styles =
            br#"<w:styles xmlns:w="w"><w:style w:type="table" w:styleId="GridTable4-Accent5">
          <w:tblStylePr w:type="firstRow"><w:tcPr><w:shd w:fill="4472C4"/></w:tcPr></w:tblStylePr>
          <w:tblStylePr w:type="band1Horz"><w:tcPr><w:shd w:fill="D9E2F3"/></w:tcPr></w:tblStylePr>
        </w:style></w:styles>"#;
        let bytes = stored_zip(&[
            (PART, document_xml),
            ("word/_rels/document.xml.rels", relationships),
            ("word/styles.xml", styles),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let cell_fill = |row, column| {
            let stable_id = format!("table:0:row:{row}:column:{column}");
            document
                .objects
                .iter()
                .find(|object| object.stable_id.contains(&stable_id))
                .map(|object| &object.visual)
        };

        assert!(matches!(
            cell_fill(0, 0),
            Some(Visual::PaintedShape {
                fill: Paint::Solid(0x4472_c4ff),
                ..
            })
        ));
        assert!(matches!(
            cell_fill(1, 1),
            Some(Visual::PaintedShape {
                fill: Paint::Solid(0xd9e2_f3ff),
                ..
            })
        ));
    }

