    #[test]
    fn renders_docx_percentage_shading() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:pPr><w:shd w:val="pct40" w:color="auto" w:fill="auto"/></w:pPr><w:r><w:t>Automatic percentage shading</w:t></w:r></w:p>
          <w:p><w:pPr><w:shd w:val="pct40" w:color="000000" w:fill="FFFFFF"/></w:pPr><w:r><w:t>Authored percentage pattern</w:t></w:r></w:p>
          <w:p><w:pPr><w:shd w:val="solid" w:color="auto" w:fill="auto"/></w:pPr><w:r><w:t>Automatic solid shading</w:t></w:r></w:p>
          <w:tbl><w:tblGrid><w:gridCol w:w="6000"/></w:tblGrid><w:tr><w:tc><w:tcPr><w:shd w:val="pct90" w:color="auto" w:fill="auto"/></w:tcPr><w:p/></w:tc></w:tr></w:tbl>
          <w:sectPr/>
        </w:body></w:document>"#;
        let document = layout_document(
            parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap(),
            Limits::default(),
            PART,
        )
        .unwrap();

        let paragraph = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("Automatic percentage shading"))
            .expect("automatic percentage shading is rendered");
        let patterned = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("Authored percentage pattern"))
            .expect("authored percentage pattern is rendered");
        let cell = document
            .objects
            .iter()
            .find(|object| object.kind == ObjectKind::Cell)
            .expect("patterned cell is rendered");
        let solid = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("Automatic solid shading"))
            .expect("automatic solid shading is rendered");
        assert!(matches!(
            rich_text_visual(&patterned.visual),
            Visual::RichText {
                fill: Paint::Pattern { preset, foreground: 0x0000_00ff, background: 0xffff_ffff },
                ..
            } if preset == "pct40"
        ));
        assert!(matches!(
            rich_text_visual(&paragraph.visual),
            Visual::RichText {
                fill: Paint::Solid(0x9999_99ff),
                ..
            }
        ));
        assert!(matches!(
            cell.visual,
            Visual::PaintedShape {
                fill: Paint::Solid(0x1a1a_1aff),
                ..
            }
        ));
        assert!(matches!(
            rich_text_visual(&solid.visual),
            Visual::RichText {
                fill: Paint::Solid(0x0000_00ff),
                ..
            }
        ));
    }

    #[test]
    fn omml_nobar_scripts_and_local_style_failure_keep_meaningful_content() {
        let xml = r#"<w:document xmlns:w="w" xmlns:m="m"><w:body>
          <w:p><m:oMath><m:f><m:fPr><m:type m:val="noBar"/></m:fPr><m:num><m:r><m:t>n</m:t></m:r></m:num><m:den><m:r><m:t>k</m:t></m:r></m:den></m:f></m:oMath></w:p>
          <w:p><m:oMath><m:sSubSup><m:e><m:r><m:t>x</m:t></m:r></m:e><m:sub><m:r><m:t>i</m:t></m:r></m:sub><m:sup><m:r><m:t>2</m:t></m:r></m:sup></m:sSubSup></m:oMath></w:p>
          <w:p><m:oMath><m:r><w:rPr><w:sz w:val="0"/></w:rPr><m:t>recoverable</m:t></m:r></m:oMath></w:p>
          <w:p><w:r><w:t>after</w:t></w:r></w:p>
        </w:body></w:document>"#;
        let document = layout_document(
            parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new()).unwrap(),
            Limits::default(),
            PART,
        )
        .unwrap();
        let parts = document
            .objects
            .iter()
            .filter(|o| o.stable_id.contains(":part:"))
            .collect::<Vec<_>>();
        assert!(
            !parts
                .iter()
                .any(|o| matches!(o.visual, Visual::PaintedShape { .. })),
            "noBar has no generated fraction line"
        );
        let find = |text: &str| {
            parts
                .iter()
                .find(|o| o.text.as_deref() == Some(text))
                .unwrap()
        };
        assert!(find("k").bounds.y > find("n").bounds.y);
        assert!(find("2").bounds.y < find("x").bounds.y);
        assert!(find("i").bounds.y > find("x").bounds.y);
        assert!((find("2").bounds.x - find("i").bounds.x).abs() < 0.01);
        for text in ["recoverable", "after"] {
            assert!(
                document
                    .objects
                    .iter()
                    .any(|o| o.text.as_deref() == Some(text))
            );
        }
        assert!(
            document
                .diagnostics
                .iter()
                .any(|d| d.message.contains("font size must be positive"))
        );
    }

    #[test]
    fn supplied_omml_equation_preserves_symbols_styles_and_structure() {
        let package = Package::open(
            include_bytes!("../../tests/fixtures/equation.docx"),
            Limits::default(),
        )
        .unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let texts = document
            .objects
            .iter()
            .filter_map(|o| o.text.as_deref())
            .collect::<Vec<_>>();
        for symbol in ["∑", "⟨", "⟩", "𝓁", "𝔢", "𝒯", "𝕖", "⇏", "↻", "⋩"] {
            assert!(
                texts.iter().any(|text| text.contains(symbol)),
                "missing {symbol}: {texts:?}"
            );
        }
        let alpha = document
            .objects
            .iter()
            .find_map(|o| {
                if let Visual::RichText { runs, .. } = rich_text_visual(&o.visual) {
                    runs.iter().find(|r| r.text == "α" && r.color == 0xff0000ff)
                } else {
                    None
                }
            })
            .expect("80pt red alpha must retain its run style");
        assert!((alpha.font_size - 80.0 * 96.0 / 72.0).abs() < 0.01);
        let matrix = document
            .objects
            .iter()
            .find(|o| o.text.as_deref() == Some("1 0\n0 1"))
            .expect("matrix retains rows");
        let cells = document
            .objects
            .iter()
            .filter(|o| o.parent_numeric_id == Some(matrix.numeric_id))
            .collect::<Vec<_>>();
        assert_eq!(cells.len(), 4);
        assert!(cells[2].bounds.y > cells[0].bounds.y);
        for cell in cells {
            assert!(
                matches!(rich_text_visual(&cell.visual), Visual::RichText { runs, .. } if runs[0].bold)
            );
        }
        let sum = document
            .objects
            .iter()
            .find(|o| o.text.as_deref() == Some("∑"))
            .unwrap();
        let lower = document
            .objects
            .iter()
            .find(|o| o.text.as_deref() == Some("n=1"))
            .unwrap();
        let upper = document
            .objects
            .iter()
            .find(|o| o.text.as_deref() == Some("∞"))
            .unwrap();
        assert!(upper.bounds.y < sum.bounds.y && lower.bounds.y > sum.bounds.y);
        assert!(
            document
                .objects
                .iter()
                .any(|o| o.stable_id.contains(":equation:")
                    && matches!(
                        o.visual,
                        Visual::PaintedShape {
                            geometry: Geometry::Rectangle,
                            ..
                        }
                    ))
        );
    }

