    #[test]
    fn renders_document_background_only_when_enabled() {
        let document_xml = br#"<w:document xmlns:w="w"><w:background w:color="548DD4" w:themeColor="text2" w:themeTint="99"/><w:body>
          <w:p/><w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr>
        </w:body></w:document>"#;
        let relationships = br#"<Relationships>
          <Relationship Id="rIdSettings" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings" Target="settings.xml"/>
          <Relationship Id="rIdTheme" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" Target="theme/theme1.xml"/>
        </Relationships>"#;
        let settings = br#"<w:settings xmlns:w="w"><w:displayBackgroundShape/></w:settings>"#;
        let theme = br#"<a:theme xmlns:a="a"><a:themeElements><a:clrScheme><a:dk2><a:srgbClr val="1F497D"/></a:dk2></a:clrScheme></a:themeElements></a:theme>"#;
        let bytes = stored_zip(&[
            (PART, document_xml),
            ("word/_rels/document.xml.rels", relationships),
            ("word/settings.xml", settings),
            ("word/theme/theme1.xml", theme),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let background = document
            .objects
            .iter()
            .find(|object| object.stable_id == "docx:page:0:background")
            .expect("enabled document background is rendered");

        assert_eq!(background.bounds.width, document.units[0].width);
        assert_eq!(background.bounds.height, document.units[0].height);
        let Visual::PaintedShape {
            fill: Paint::Solid(color),
            stroke: Paint::None,
            ..
        } = background.visual
        else {
            panic!("document background must be a solid fill without a stroke");
        };
        assert_eq!(color, 0x548d_d4ff);
        assert_eq!(background.z, 0);

        let bytes = stored_zip(&[
            (PART, document_xml),
            ("word/_rels/document.xml.rels", relationships),
            ("word/settings.xml", br#"<w:settings xmlns:w="w"/>"#),
            ("word/theme/theme1.xml", theme),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        assert!(
            !document
                .objects
                .iter()
                .any(|object| object.stable_id.ends_with(":background"))
        );
    }

    #[test]
    fn consumer_confidence_signed_indents_keep_labels_on_one_line() {
        let package = Package::open(
            include_bytes!("../../tests/fixtures/word-consumer-confidence.docx"),
            Limits::default(),
        )
        .unwrap();
        // macOS Comic Sans MS advances measured at 1000pt, in 1/2048 em units.
        let advances = [
            (' ', 612),
            (':', 612),
            ('D', 1478),
            ('N', 1632),
            ('R', 1287),
            ('S', 1420),
            ('W', 2129),
            ('a', 1048),
            ('e', 1122),
            ('m', 1591),
            ('o', 1077),
            ('p', 1095),
            ('r', 984),
            ('s', 997),
            ('t', 965),
            ('y', 1066),
        ]
        .map(|(character, units)| (character, units as f32 / 2048.0));
        let metrics = font_metrics("Comic Sans MS", &advances);
        let document = parse_with_font_metrics(&package, PART, Vec::new(), &metrics).unwrap();
        for (text, x, width) in [
            ("Water System Name:", 78.0, 150.0),
            ("Report Date:", 522.0, 90.0),
        ] {
            let paragraph = document
                .objects
                .iter()
                .find(|object| object.text.as_deref() == Some(text))
                .unwrap();
            assert!(
                (paragraph.bounds.x - x).abs() < 0.01,
                "{text}: {:?}",
                paragraph.bounds
            );
            assert!(
                (paragraph.bounds.width - width).abs() < 0.01,
                "{text}: {:?}",
                paragraph.bounds
            );
            let Visual::RichText { line_height, .. } = rich_text_visual(&paragraph.visual) else {
                panic!("label must be rendered as text");
            };
            assert!(
                paragraph.bounds.height <= line_height + 0.01,
                "{text} must fit on one line: {:?}",
                paragraph.bounds
            );
        }
    }

    #[test]
    fn preserves_signed_indents_in_direct_styles_and_numbering() {
        for (left_name, right_name) in [("left", "right"), ("start", "end")] {
            for (left, right) in [(-90, -72), (0, 0), (90, 72)] {
                let ind = format!(r#"<w:ind w:{left_name}="{left}" w:{right_name}="{right}"/>"#);
                let expected = (
                    left as f32 / TWIPS_PER_CSS_PIXEL,
                    right as f32 / TWIPS_PER_CSS_PIXEL,
                );
                let xml = format!(
                    r#"<w:document xmlns:w="w"><w:body><w:p><w:pPr>{ind}</w:pPr><w:r><w:t>Label</w:t></w:r></w:p></w:body></w:document>"#
                );
                let parsed =
                    parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new())
                        .unwrap();
                let Block::Paragraph(paragraph) = &parsed.blocks[0] else {
                    panic!("paragraph");
                };
                assert_eq!((paragraph.indent_left, paragraph.indent_right), expected);

                let xml = format!(
                    r#"<w:styles xmlns:w="w"><w:style w:type="paragraph" w:styleId="Base"><w:pPr>{ind}</w:pPr></w:style><w:style w:type="paragraph" w:styleId="Child"><w:basedOn w:val="Base"/></w:style></w:styles>"#
                );
                let styles = super::parse_styles_xml(
                    xml.as_bytes(),
                    Limits::default(),
                    "word/styles.xml",
                    &super::DocxTheme::default(),
                )
                .unwrap();
                let style = styles.properties_for(Some("Child"));
                assert_eq!(
                    (style.indent_left, style.indent_right),
                    (Some(expected.0), Some(expected.1))
                );

                let xml = format!(
                    r#"<w:numbering xmlns:w="w"><w:abstractNum w:abstractNumId="0"><w:lvl w:ilvl="0"><w:numFmt w:val="decimal"/><w:lvlText w:val="%1."/><w:pPr>{ind}</w:pPr></w:lvl></w:abstractNum></w:numbering>"#
                );
                let numbering = super::parse_numbering_xml(
                    xml.as_bytes(),
                    Limits::default(),
                    "word/numbering.xml",
                    &mut Vec::new(),
                )
                .unwrap();
                let level = &numbering.levels[&(0, 0)];
                assert_eq!(
                    (level.indent_left, level.indent_right),
                    (Some(expected.0), Some(expected.1))
                );
            }
        }
    }

