    #[test]
    fn splits_table_rows_and_repeats_marked_header_rows() {
        let long_text = "content ".repeat(120);
        let xml = format!(
            r#"<w:document xmlns:w="w"><w:body>
              <w:tbl><w:tblGrid><w:gridCol w:w="2400"/></w:tblGrid>
                <w:tr><w:trPr><w:tblHeader/></w:trPr><w:tc><w:p><w:r><w:t>Header</w:t></w:r></w:p></w:tc></w:tr>
                <w:tr><w:tc><w:p><w:r><w:t>{long_text}</w:t></w:r></w:p></w:tc></w:tr>
              </w:tbl>
              <w:sectPr><w:pgSz w:w="3000" w:h="3000"/><w:pgMar w:top="150" w:right="150" w:bottom="150" w:left="150"/></w:sectPr>
            </w:body></w:document>"#
        );
        let parsed =
            parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new()).unwrap();
        let Block::Table(table) = &parsed.blocks[0] else {
            panic!("table block must be parsed");
        };
        assert!(table.rows[0].repeat_header);

        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        assert!(document.units.len() > 1);
        assert!(document.objects.iter().any(|object| {
            object.unit_index == 1
                && object.source.locator
                    == SourceLocator::Docx {
                        kind: "table-cell",
                        paragraph_id: None,
                        paragraph_index: None,
                        drawing_id: None,
                        row: Some(0),
                        column: Some(0),
                        text_range: None,
                        action: None,
                    }
        }));
    }

