    #[test]
    fn real_docx_legal_numbering_uses_decimal_for_every_placeholder() {
        let package = Package::open(
            include_bytes!("../../tests/fixtures/ooxml-legal-numbering.docx"),
            Limits::default(),
        )
        .unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let labels = document
            .objects
            .iter()
            .filter(|object| object.stable_id.starts_with("docx:numbering:"))
            .map(|object| object.text.as_deref().unwrap_or_default())
            .collect::<Vec<_>>();
        let decimal = [
            "A.", "A.a", "A.b", "1.2.1", "1.2.2", "1.2.3", "B.", "B.a", "2.1.1", "2.1.2", "2.1.3",
        ];
        assert_eq!(labels, decimal);

        let original = package.part("word/numbering.xml").unwrap().unwrap();
        let original = std::str::from_utf8(&original).unwrap();
        assert!(original.contains("<w:isLgl/>"));
        for (flag, legal) in [
            ("", false),
            (r#"<w:isLgl w:val="0"/>"#, false),
            (r#"<w:isLgl w:val="false"/>"#, false),
            (r#"<w:isLgl w:val="1"/>"#, true),
            (r#"<w:isLgl w:val="true"/>"#, true),
        ] {
            let numbering = original.replace("<w:isLgl/>", flag);
            let parts = package
                .entry_names()
                .map(|name| {
                    let bytes = if name == "word/numbering.xml" {
                        numbering.as_bytes().to_vec()
                    } else {
                        package.part(name).unwrap().unwrap().into_vec()
                    };
                    (name, bytes)
                })
                .collect::<Vec<_>>();
            let entries = parts
                .iter()
                .map(|(name, bytes)| (*name, bytes.as_slice()))
                .collect::<Vec<_>>();
            let bytes = stored_zip(&entries);
            let package = Package::open(&bytes, Limits::default()).unwrap();
            let document = parse(&package, PART, Vec::new()).unwrap();
            let labels = document
                .objects
                .iter()
                .filter(|object| object.stable_id.starts_with("docx:numbering:"))
                .map(|object| object.text.as_deref().unwrap_or_default())
                .collect::<Vec<_>>();
            let expected = if legal {
                decimal
            } else {
                [
                    "A.", "A.a", "A.b", "A.b.i", "A.b.ii", "A.b.iii", "B.", "B.a", "B.a.i",
                    "B.a.ii", "B.a.iii",
                ]
            };
            assert_eq!(labels, expected, "isLgl: {flag}");
        }
    }

