    #[test]
    fn zero_indent_numbering_honors_suffix_and_skips_tabs_inside_the_marker() {
        let relationships = br#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="num" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/numbering" Target="numbering.xml"/></Relationships>"#;
        for (suffix, tabs, expected) in [
            ("tab", "", 36.0),
            (
                "tab",
                r#"<w:tabs><w:tab w:val="left" w:pos="90"/></w:tabs>"#,
                36.0,
            ),
            (
                "tab",
                r#"<w:tabs><w:tab w:val="left" w:pos="720"/></w:tabs>"#,
                48.0,
            ),
            ("space", "", DEFAULT_FONT_SIZE * 0.55 * 3.0),
            ("nothing", "", DEFAULT_FONT_SIZE * 0.55 * 2.0),
        ] {
            let xml = format!(
                r#"<w:document xmlns:w="w"><w:body><w:p><w:pPr><w:numPr><w:ilvl w:val="0"/><w:numId w:val="1"/></w:numPr><w:ind w:left="0" w:firstLine="0"/>{tabs}</w:pPr><w:r><w:t>Body</w:t><w:br w:type="page"/><w:t>Continuation</w:t></w:r></w:p></w:body></w:document>"#
            );
            let numbering = format!(
                r#"<w:numbering xmlns:w="w"><w:abstractNum w:abstractNumId="1"><w:lvl w:ilvl="0"><w:numFmt w:val="decimal"/><w:lvlText w:val="%1."/><w:lvlJc w:val="left"/><w:suff w:val="{suffix}"/></w:lvl></w:abstractNum><w:num w:numId="1"><w:abstractNumId w:val="1"/></w:num></w:numbering>"#
            );
            let bytes = stored_zip(&[
                (PART, xml.as_bytes()),
                ("word/_rels/document.xml.rels", relationships),
                ("word/numbering.xml", numbering.as_bytes()),
            ]);
            let package = Package::open(&bytes, Limits::default()).unwrap();
            let document = parse(&package, PART, Vec::new()).unwrap();
            let body = document
                .objects
                .iter()
                .find(|o| o.text.as_deref() == Some("Body"))
                .unwrap();
            let Visual::TextLayout { layout, .. } = &body.visual else {
                panic!("body layout")
            };
            assert!(
                (layout.first_line_indent - expected).abs() < 0.01,
                "{suffix} {tabs}"
            );
            assert_eq!(
                layout.hanging_indent, 0.0,
                "continuation must keep the zero indent"
            );
            let continuation = document
                .objects
                .iter()
                .find(|o| o.text.as_deref() == Some("Continuation"))
                .unwrap();
            let Visual::TextLayout { layout, .. } = &continuation.visual else {
                panic!("continuation layout")
            };
            assert_eq!(
                layout.first_line_indent, 0.0,
                "a new page must not repeat the marker's first-line offset"
            );
        }
    }

