    #[test]
    fn keeps_footnote_reference_style_inline_in_body_and_note_text() {
        let document_xml = br#"<w:document xmlns:w="w"><w:body><w:p>
          <w:r><w:t>Lorem ipsum</w:t></w:r>
          <w:r><w:rPr><w:rStyle w:val="FootnoteReference"/></w:rPr><w:footnoteReference w:id="1"/></w:r>
        </w:p><w:sectPr/></w:body></w:document>"#;
        let relationships = br#"<Relationships>
          <Relationship Id="rIdStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
          <Relationship Id="rIdFootnotes" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footnotes" Target="footnotes.xml"/>
        </Relationships>"#;
        let styles = br#"<w:styles xmlns:w="w">
          <w:docDefaults><w:rPrDefault><w:rPr><w:sz w:val="22"/></w:rPr></w:rPrDefault></w:docDefaults>
          <w:style w:type="paragraph" w:default="1" w:styleId="Normal"/>
          <w:style w:type="paragraph" w:styleId="FootnoteText"><w:basedOn w:val="Normal"/><w:rPr><w:sz w:val="20"/></w:rPr></w:style>
          <w:style w:type="character" w:styleId="DefaultParagraphFont"/>
          <w:style w:type="character" w:styleId="FootnoteReference"><w:basedOn w:val="DefaultParagraphFont"/><w:rPr><w:vertAlign w:val="superscript"/></w:rPr></w:style>
        </w:styles>"#;
        let footnotes = br#"<w:footnotes xmlns:w="w"><w:footnote w:id="1"><w:p>
          <w:pPr><w:pStyle w:val="FootnoteText"/></w:pPr>
          <w:r><w:rPr><w:rStyle w:val="FootnoteReference"/></w:rPr><w:footnoteRef/></w:r>
          <w:r><w:t xml:space="preserve"> Footnote text</w:t></w:r>
        </w:p></w:footnote></w:footnotes>"#;
        let bytes = stored_zip(&[
            (PART, document_xml),
            ("word/_rels/document.xml.rels", relationships),
            ("word/styles.xml", styles),
            ("word/footnotes.xml", footnotes),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let body = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("Lorem ipsum1"))
            .expect("footnote reference stays inline with body text");
        let note = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("1 Footnote text"))
            .expect("footnote reference stays inline with note text");
        assert_eq!(document.units.len(), 1);
        assert_eq!(note.unit_index, 0);
        assert!(note.bounds.y > 800.0);
        let Visual::RichText {
            runs: body_runs, ..
        } = rich_text_visual(&body.visual)
        else {
            panic!("body paragraph must use rich text");
        };
        let Visual::RichText {
            runs: note_runs, ..
        } = rich_text_visual(&note.visual)
        else {
            panic!("footnote paragraph must use rich text");
        };

        assert_eq!(body_runs.len(), 2);
        assert_eq!(body_runs[1].text, "1");
        assert!(body_runs[1].font_size < body_runs[0].font_size);
        assert!(body_runs[1].baseline_shift > 0.0);
        assert_eq!(note_runs.len(), 2);
        assert_eq!(note_runs[0].text, "1");
        assert!(note_runs[0].font_size < note_runs[1].font_size);
        assert!(note_runs[0].baseline_shift > 0.0);
    }

