    #[test]
    fn hides_comments_without_changing_page_layout() {
        let document_xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:r><w:t>Body</w:t><w:commentReference w:id="2"/></w:r></w:p>
          <w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1800" w:bottom="1440" w:left="1800"/></w:sectPr>
        </w:body></w:document>"#;
        let relationships = br#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
          <Relationship Id="rIdComments" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/comments" Target="comments.xml"/>
        </Relationships>"#;
        let comments = br#"<w:comments xmlns:w="w"><w:comment w:id="2"><w:p><w:r><w:t>Review note</w:t></w:r></w:p></w:comment></w:comments>"#;
        let bytes = stored_zip(&[
            (PART, document_xml),
            ("word/_rels/document.xml.rels", relationships),
            ("word/comments.xml", comments),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        let body = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("Body"))
            .expect("body is rendered");

        assert_eq!(document.units.len(), 1);
        assert_eq!(body.bounds.x, 1800.0 / TWIPS_PER_CSS_PIXEL);
        assert!(document.objects.iter().any(|object| {
            object.source.part == "word/comments.xml"
                && object.text.as_deref() == Some("Review note")
                && matches!(object.visual, Visual::None)
        }));
        assert!(
            document
                .objects
                .iter()
                .all(|object| object.text.as_deref() != Some("Comment 2"))
        );
    }

