    #[test]
    fn applies_page_geometry_at_each_section_boundary() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:pPr><w:sectPr><w:pgSz w:w="9000" w:h="12000"/><w:pgMar w:top="600" w:right="600" w:bottom="600" w:left="600"/></w:sectPr></w:pPr><w:r><w:t>Section one</w:t></w:r></w:p>
          <w:p><w:r><w:t>Section two</w:t></w:r></w:p>
          <w:sectPr><w:pgSz w:w="12000" w:h="9000"/><w:pgMar w:top="900" w:right="900" w:bottom="900" w:left="900"/></w:sectPr>
        </w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        assert_eq!(document.units.len(), 2);
        assert_eq!(
            (document.units[0].width, document.units[0].height),
            (600.0, 800.0)
        );
        assert_eq!(
            (document.units[1].width, document.units[1].height),
            (800.0, 600.0)
        );
        assert_eq!(document.objects[0].unit_index, 0);
        assert_eq!(document.objects[1].unit_index, 1);
    }

    #[test]
    fn does_not_paginate_an_empty_section_break_paragraph() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:tbl><w:tblGrid><w:gridCol w:w="2700"/></w:tblGrid><w:tr><w:trPr><w:trHeight w:val="2500" w:hRule="atLeast"/></w:trPr><w:tc><w:p><w:r><w:t>Full page table</w:t></w:r></w:p></w:tc></w:tr></w:tbl>
          <w:p/>
          <w:p><w:pPr><w:sectPr><w:pgSz w:w="3000" w:h="3000"/><w:pgMar w:top="150" w:right="150" w:bottom="150" w:left="150"/></w:sectPr></w:pPr></w:p>
          <w:p><w:r><w:t>Next section</w:t></w:r></w:p>
          <w:sectPr><w:pgSz w:w="3000" w:h="3000"/><w:pgMar w:top="150" w:right="150" w:bottom="150" w:left="150"/></w:sectPr>
        </w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let Block::Paragraph(spacer) = &parsed.blocks[1] else {
            panic!("paragraph before a section break must remain a paragraph");
        };
        assert!(!spacer.section_break);
        let document = layout_document(parsed, Limits::default(), PART).unwrap();

        assert_eq!(document.units.len(), 3);
        let next = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("Next section"))
            .unwrap();
        assert_eq!(next.unit_index, 2);
    }

