    #[test]
    fn lays_out_percentage_width_floating_tables_at_the_bottom_margin() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:r><w:t>Lead text</w:t></w:r></w:p>
          <w:tbl><w:tblPr><w:tblpPr w:tblpXSpec="center" w:tblpYSpec="bottom"/><w:tblW w:w="4000" w:type="pct"/><w:tblBorders><w:left w:val="single" w:sz="18" w:color="4F81BD"/></w:tblBorders></w:tblPr><w:tblGrid><w:gridCol w:w="7096"/></w:tblGrid><w:tr><w:tc><w:p><w:r><w:t>Bottom table</w:t></w:r></w:p></w:tc></w:tr></w:tbl>
          <w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1800" w:right="1800" w:bottom="1800" w:left="1800"/></w:sectPr>
        </w:body></w:document>"#;
        for fixed in [false, true] {
            let xml = std::str::from_utf8(xml).unwrap().replace(
                "<w:tblPr>",
                if fixed {
                    "<w:tblPr><w:tblLayout w:type=\"fixed\"/>"
                } else {
                    "<w:tblPr>"
                },
            );
            let parsed =
                parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new()).unwrap();
            let document = layout_document(parsed, Limits::default(), PART).unwrap();
            let table = document
                .objects
                .iter()
                .find(|object| object.kind == ObjectKind::Table)
                .expect("floating table is rendered");

            assert_eq!(document.units.len(), 1);
            let width = if fixed {
                460.8
            } else {
                7096.0 / TWIPS_PER_CSS_PIXEL
            };
            assert!((table.bounds.width - width).abs() < 0.01);
            assert!((table.bounds.x - (816.0 - width) / 2.0).abs() < 0.01);
            assert!((table.bounds.y + table.bounds.height - 936.0).abs() < 0.01);
            assert!(matches!(table.visual, Visual::None));
            assert!(
                document
                    .objects
                    .iter()
                    .any(|object| object.stable_id.ends_with(":border:left"))
            );
            assert!(!document.objects.iter().any(|object| {
                [":border:top", ":border:right", ":border:bottom"]
                    .iter()
                    .any(|suffix| object.stable_id.ends_with(suffix))
            }));
        }
    }

    #[test]
    fn merges_style_tabs_by_position_and_preserves_clear_through_inheritance() {
        let document_xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:pPr><w:pStyle w:val="Child"/></w:pPr><w:r><w:t>Child</w:t></w:r></w:p>
          <w:p><w:pPr><w:pStyle w:val="Grandchild"/><w:tabs><w:tab w:val="clear" w:pos="1620"/><w:tab w:val="left" w:pos="2700"/></w:tabs></w:pPr><w:r><w:t>Grandchild</w:t></w:r></w:p>
        </w:body></w:document>"#;
        let styles = br#"<w:styles xmlns:w="w">
          <w:style w:type="paragraph" w:default="1" w:styleId="Base"><w:pPr><w:tabs><w:tab w:val="left" w:pos="540"/><w:tab w:val="left" w:pos="1080"/><w:tab w:val="left" w:pos="1620"/></w:tabs></w:pPr></w:style>
          <w:style w:type="paragraph" w:styleId="Child"><w:basedOn w:val="Base"/><w:pPr><w:tabs><w:tab w:val="clear" w:pos="1080"/><w:tab w:val="right" w:leader="dot" w:pos="2160"/></w:tabs></w:pPr></w:style>
          <w:style w:type="paragraph" w:styleId="Grandchild"><w:basedOn w:val="Child"/><w:pPr><w:tabs><w:tab w:val="clear" w:pos="540"/><w:tab w:val="center" w:pos="1080"/></w:tabs></w:pPr></w:style>
        </w:styles>"#;
        let relationships = br#"<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="styles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>"#;
        let bytes = stored_zip(&[
            (PART, document_xml),
            ("word/styles.xml", styles),
            ("word/_rels/document.xml.rels", relationships),
        ]);
        let package = Package::open(&bytes, Limits::default()).unwrap();
        let document = parse(&package, PART, Vec::new()).unwrap();
        for (text, expected) in [
            ("Child", vec![36.0, 108.0, 144.0]),
            ("Grandchild", vec![72.0, 144.0, 180.0]),
        ] {
            let object = document
                .objects
                .iter()
                .find(|object| object.text.as_deref() == Some(text))
                .unwrap();
            let Visual::TextLayout { layout, .. } = &object.visual else {
                panic!("paragraph layout")
            };
            assert_eq!(
                layout
                    .tab_stops
                    .iter()
                    .map(|stop| stop.position)
                    .collect::<Vec<_>>(),
                expected
            );
            let page_tab = layout
                .tab_stops
                .iter()
                .find(|stop| stop.position == 144.0)
                .unwrap();
            assert_eq!(page_tab.align, TextAlign::End);
            assert_eq!(page_tab.leader, TextTabLeader::Dot);
            if text == "Grandchild" {
                assert_eq!(layout.tab_stops[0].align, TextAlign::Center);
            }
        }
    }

    #[test]
    fn preserves_right_tab_alignment_and_dot_leader() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:pPr><w:tabs><w:tab w:val="right" w:leader="dot" w:pos="10220"/></w:tabs></w:pPr><w:r><w:t>Title</w:t><w:tab/><w:t>7</w:t></w:r></w:p>
          <w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr>
        </w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let Visual::TextLayout { layout, .. } = &document.objects[0].visual else {
            panic!("tabbed paragraph must use text layout");
        };

        assert_eq!(layout.tab_stops.len(), 1);
        assert!((layout.tab_stops[0].position - 10220.0 / 15.0).abs() < 0.001);
        assert_eq!(layout.tab_stops[0].align, TextAlign::End);
        assert_eq!(layout.tab_stops[0].leader, TextTabLeader::Dot);
    }

