    #[test]
    fn balances_a_short_continuous_section_across_columns() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:pPr><w:sectPr><w:pgSz w:w="6000" w:h="6000"/><w:pgMar w:top="600" w:right="600" w:bottom="600" w:left="600"/><w:cols/></w:sectPr></w:pPr><w:r><w:t>Heading</w:t></w:r></w:p>
          <w:p><w:pPr><w:sectPr><w:type w:val="continuous"/><w:pgSz w:w="6000" w:h="6000"/><w:pgMar w:top="600" w:right="600" w:bottom="600" w:left="600"/><w:cols w:num="2" w:space="300" w:sep="1"/></w:sectPr></w:pPr><w:r><w:t>A</w:t><w:br/><w:t>B</w:t><w:br/><w:t>C</w:t><w:br/><w:t>D</w:t><w:br/><w:t>E</w:t></w:r></w:p>
          <w:p><w:r><w:t>After</w:t></w:r></w:p>
          <w:sectPr><w:type w:val="continuous"/><w:pgSz w:w="6000" w:h="6000"/><w:pgMar w:top="600" w:right="600" w:bottom="600" w:left="600"/><w:cols/></w:sectPr>
        </w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let fragments = document
            .objects
            .iter()
            .filter(|object| {
                object
                    .text
                    .as_deref()
                    .is_some_and(|text| text != "After" && text != "Heading" && !text.is_empty())
            })
            .collect::<Vec<_>>();
        let after = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("After"))
            .unwrap();

        assert_eq!(document.units.len(), 1);
        assert_eq!(fragments.len(), 2);
        assert!(fragments[0].bounds.x < fragments[1].bounds.x);
        assert!(after.bounds.y >= fragments[0].bounds.y + fragments[0].bounds.height);
        assert!(after.bounds.y >= fragments[1].bounds.y + fragments[1].bounds.height);
        let separator = document
            .objects
            .iter()
            .find(|object| object.stable_id.contains("column-separator"))
            .unwrap();
        assert!(separator.bounds.x > fragments[0].bounds.x + fragments[0].bounds.width);
        assert!(separator.bounds.x < fragments[1].bounds.x);
    }

