    #[test]
    fn balances_wrapped_text_from_the_actual_column_fragments() {
        let text = "There are three equally wide columns of text here. Each column is 1.625 inches (that's one and five-eighths of an inch) wide. The three columns here are both of this width. There is 0.5 inches between the columns. In addition, the left margin of the first column and the right margin of the third column should line up with the left and right margins of the first column. The columns should appear balanced, the text being fully justified. Verify that each of these columns are indeed 1.625 inches wide. Please also verify the 0.5 inch space between the columns. The edges should not appear ragged.";
        let xml = format!(
            r#"<w:document xmlns:w="w"><w:body>
              <w:p><w:pPr><w:sectPr><w:pgSz w:w="12240" w:h="6000"/><w:pgMar w:top="600" w:right="1800" w:bottom="600" w:left="1800"/><w:cols/></w:sectPr></w:pPr><w:r><w:t>Heading</w:t></w:r></w:p>
              <w:p><w:pPr><w:sectPr><w:type w:val="continuous"/><w:pgSz w:w="12240" w:h="6000"/><w:pgMar w:top="600" w:right="1800" w:bottom="600" w:left="1800"/><w:cols w:num="3" w:space="720"/></w:sectPr></w:pPr><w:r><w:t>{text}</w:t></w:r></w:p>
              <w:p><w:r><w:t>After</w:t></w:r></w:p>
              <w:sectPr><w:type w:val="continuous"/><w:pgSz w:w="12240" w:h="6000"/><w:pgMar w:top="600" w:right="1800" w:bottom="600" w:left="1800"/><w:cols/></w:sectPr>
            </w:body></w:document>"#
        );
        let parsed =
            parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let fragments = document
            .objects
            .iter()
            .filter(|object| {
                object
                    .text
                    .as_deref()
                    .is_some_and(|value| !value.is_empty() && text.contains(value))
            })
            .collect::<Vec<_>>();

        assert_eq!(fragments.len(), 3);
        assert!(fragments.iter().all(|fragment| fragment.unit_index == 0));
        assert_eq!(
            fragments
                .iter()
                .filter_map(|fragment| fragment.text.as_deref())
                .collect::<String>(),
            text
        );
    }

    #[test]
    fn balances_authored_unequal_section_columns_at_their_own_widths() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p><w:pPr><w:sectPr><w:pgSz w:w="6000" w:h="6000"/><w:pgMar w:top="600" w:right="600" w:bottom="600" w:left="600"/><w:cols/></w:sectPr></w:pPr><w:r><w:t>Heading</w:t></w:r></w:p>
          <w:p><w:pPr><w:sectPr><w:type w:val="continuous"/><w:pgSz w:w="6000" w:h="6000"/><w:pgMar w:top="600" w:right="600" w:bottom="600" w:left="600"/><w:cols w:num="2" w:equalWidth="0"><w:col w:w="1200" w:space="300"/><w:col w:w="3300"/></w:cols></w:sectPr></w:pPr><w:r><w:rPr><w:rFonts w:ascii="P0 Sans" w:hAnsi="P0 Sans"/></w:rPr><w:t>A</w:t><w:br/><w:t>B</w:t><w:br/><w:t>C</w:t><w:br/><w:t>D</w:t><w:br/><w:t>E</w:t></w:r></w:p>
          <w:p><w:r><w:t>After</w:t></w:r></w:p>
          <w:sectPr><w:type w:val="continuous"/><w:pgSz w:w="6000" w:h="6000"/><w:pgMar w:top="600" w:right="600" w:bottom="600" w:left="600"/><w:cols/></w:sectPr>
        </w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let metrics = font_metric_with_line_height("P0 Sans", 'A', 0.9, 1.15, false);
        let document =
            layout_document_with_font_metrics(parsed, Limits::default(), PART, &metrics).unwrap();
        let fragments = document
            .objects
            .iter()
            .filter(|object| {
                object
                    .text
                    .as_deref()
                    .is_some_and(|text| text != "After" && text != "Heading" && !text.is_empty())
            })
            .collect::<Vec<_>>();

        assert_eq!(fragments.len(), 2);
        assert!((fragments[0].bounds.width - 80.0).abs() < 0.001);
        assert!((fragments[1].bounds.width - 220.0).abs() < 0.001);
        assert_eq!(fragments[0].unit_index, fragments[1].unit_index);
    }

    #[test]
    fn merged_cell_height_is_shared_in_body_and_textbox_tables() {
        let paragraph = |text| {
            format!(
                r#"<w:p><w:pPr><w:spacing w:before="0" w:after="0" w:line="300" w:lineRule="exact"/></w:pPr><w:r><w:t>{text}</w:t></w:r></w:p>"#
            )
        };
        for host in ["body", "textbox"] {
            for merge in ["valid", "restart-only", "orphan"] {
                let start = if merge == "orphan" {
                    "continue"
                } else {
                    "restart"
                };
                let continuation = if merge == "valid" { "<w:vMerge/>" } else { "" };
                let table = format!(
                    r#"<w:tbl><w:tblPr><w:tblCellMar><w:top w:w="0"/><w:bottom w:w="0"/></w:tblCellMar></w:tblPr><w:tblGrid><w:gridCol w:w="3000"/><w:gridCol w:w="3000"/></w:tblGrid>
                  <w:tr><w:tc><w:tcPr><w:vMerge w:val="{start}"/></w:tcPr>{}{}{}{}</w:tc><w:tc>{}</w:tc></w:tr>
                  <w:tr><w:tc><w:tcPr>{continuation}</w:tcPr>{}</w:tc><w:tc>{}</w:tc></w:tr>
                </w:tbl>"#,
                    paragraph("L1"),
                    paragraph("L2"),
                    paragraph("L3"),
                    paragraph("L4"),
                    paragraph("First"),
                    paragraph(""),
                    paragraph("Second")
                );
                let content = if host == "textbox" {
                    format!(
                        r#"<w:p><w:r><w:pict><v:shape style="position:absolute;width:300pt;height:200pt"><v:textbox inset="0,0,0,0"><w:txbxContent>{table}</w:txbxContent></v:textbox></v:shape></w:pict></w:r></w:p>"#
                    )
                } else {
                    table
                };
                let xml = format!(
                    r#"<w:document xmlns:w="w" xmlns:v="v"><w:body>{content}<w:sectPr/></w:body></w:document>"#
                );
                let parsed =
                    parse_document_xml(xml.as_bytes(), Limits::default(), PART, Vec::new())
                        .unwrap();
                let document = layout_document(parsed, Limits::default(), PART).unwrap();
                let first = document
                    .objects
                    .iter()
                    .find(|o| o.text.as_deref() == Some("First"))
                    .unwrap();
                let second = document
                    .objects
                    .iter()
                    .find(|o| o.text.as_deref() == Some("Second"))
                    .unwrap();
                assert!(
                    (second.bounds.y - first.bounds.y - if merge == "valid" { 20.0 } else { 80.0 })
                        .abs()
                        < 0.01,
                    "{host} {merge}: first {:?}, second {:?}",
                    first.bounds,
                    second.bounds
                );
                let last = document
                    .objects
                    .iter()
                    .find(|o| o.text.as_deref() == Some("L4"))
                    .unwrap();
                let cell = &document.objects[last.parent_numeric_id.unwrap() as usize];
                assert!((cell.bounds.height - 80.0).abs() < 0.01, "{host} {merge}");
                assert!(
                    last.bounds.y + last.bounds.height <= cell.bounds.y + cell.bounds.height + 0.01
                );
            }
        }
    }

