    #[test]
    fn table_cells_do_not_compress_auto_line_spacing_below_the_natural_line_box() {
        let xml = br#"<w:document xmlns:w="w"><w:body><w:tbl>
          <w:tblPr><w:tblCellMar><w:top w:w="0" w:type="dxa"/><w:left w:w="0" w:type="dxa"/><w:bottom w:w="0" w:type="dxa"/><w:right w:w="0" w:type="dxa"/></w:tblCellMar></w:tblPr>
          <w:tblGrid><w:gridCol w:w="6000"/></w:tblGrid>
          <w:tr><w:trPr><w:trHeight w:val="302" w:hRule="atLeast"/></w:trPr>
            <w:tc><w:tcPr><w:vAlign w:val="center"/></w:tcPr><w:p><w:pPr><w:spacing w:before="277" w:after="0" w:line="199" w:lineRule="auto"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="P0 Sans" w:hAnsi="P0 Sans"/><w:sz w:val="19"/></w:rPr><w:t>A</w:t></w:r></w:p></w:tc>
          </w:tr>
        </w:tbl><w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let metrics = font_metric_with_line_height("P0 Sans", 'A', 0.5, 1.34, false);
        let document =
            layout_document_with_font_metrics(parsed, Limits::default(), PART, &metrics).unwrap();
        let cell = document
            .objects
            .iter()
            .find(|object| object.kind == ObjectKind::Cell)
            .unwrap();
        let paragraph = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("A"))
            .unwrap();
        let Visual::RichText { line_height, .. } = rich_text_visual(&paragraph.visual) else {
            panic!("table paragraph must use rich text");
        };
        let natural_line_height = 19.0 / 2.0 * POINTS_TO_CSS_PIXELS * 1.34;

        assert!((*line_height - natural_line_height).abs() < 0.001);
        assert!(
            (cell.bounds.height - (277.0 / TWIPS_PER_CSS_PIXEL + natural_line_height)).abs()
                < 0.001
        );
    }

