    #[test]
    fn honors_a_centered_table_width_beyond_the_text_margins() {
        let xml = br#"<w:document xmlns:w="w"><w:body><w:tbl>
          <w:tblPr><w:tblW w:w="8642" w:type="dxa"/><w:jc w:val="center"/></w:tblPr>
          <w:tblGrid><w:gridCol w:w="4321"/><w:gridCol w:w="4321"/></w:tblGrid>
          <w:tr>
            <w:tc><w:p><w:r><w:t>Left</w:t></w:r></w:p></w:tc>
            <w:tc><w:p><w:r><w:t>Right</w:t></w:r></w:p></w:tc>
          </w:tr>
        </w:tbl><w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1800" w:right="1800" w:bottom="1800" w:left="1800"/></w:sectPr></w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let table = document
            .objects
            .iter()
            .find(|object| object.kind == ObjectKind::Table)
            .unwrap();
        let cells = document
            .objects
            .iter()
            .filter(|object| object.kind == ObjectKind::Cell)
            .collect::<Vec<_>>();

        let page_width = 11906.0 / TWIPS_PER_CSS_PIXEL;
        let table_width = 8642.0 / TWIPS_PER_CSS_PIXEL;
        let table_x = (page_width - table_width) / 2.0;
        assert!((table.bounds.x - table_x).abs() < 0.01);
        assert!((table.bounds.width - table_width).abs() < 0.01);
        assert!((cells[0].bounds.x - table_x).abs() < 0.01);
        assert!((cells[0].bounds.width - table_width / 2.0).abs() < 0.01);
        assert!((cells[1].bounds.x - (table_x + table_width / 2.0)).abs() < 0.01);
    }

