    #[test]
    fn preserves_thicker_outer_table_borders() {
        let xml = br#"<w:document xmlns:w="w"><w:body><w:tbl>
          <w:tblPr><w:tblBorders>
            <w:top w:val="single" w:sz="18" w:color="000000"/>
            <w:left w:val="single" w:sz="18" w:color="000000"/>
            <w:bottom w:val="single" w:sz="18" w:color="000000"/>
            <w:right w:val="single" w:sz="18" w:color="000000"/>
            <w:insideH w:val="single" w:sz="6" w:color="000000"/>
            <w:insideV w:val="single" w:sz="6" w:color="000000"/>
          </w:tblBorders></w:tblPr>
          <w:tblGrid><w:gridCol w:w="6000"/></w:tblGrid>
          <w:tr><w:tc><w:p><w:r><w:t>Bordered</w:t></w:r></w:p></w:tc></w:tr>
        </w:tbl><w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let table = document
            .objects
            .iter()
            .find(|object| object.kind == ObjectKind::Table)
            .unwrap();
        let cell = document
            .objects
            .iter()
            .find(|object| object.kind == ObjectKind::Cell)
            .unwrap();

        assert!(matches!(
            cell.visual,
            Visual::PaintedShape {
                fill: Paint::Solid(0x0000_0000),
                ..
            }
        ));

        assert!(matches!(table.visual, Visual::None));
        assert_eq!(
            document
                .objects
                .iter()
                .filter(|object| {
                    object.stable_id.contains(":border:")
                        && matches!(
                            object.visual,
                            Visual::PaintedShape { stroke_width, .. }
                                if (stroke_width - 2.88).abs() < 0.01
                        )
                })
                .count(),
            4
        );
        assert!(matches!(
            cell.visual,
            Visual::PaintedShape { stroke_width, .. }
                if (stroke_width - 0.96).abs() < 0.01
        ));
    }

    #[test]
    fn keeps_different_double_cell_borders_separate() {
        let xml = br#"<w:document xmlns:w="w"><w:body><w:tbl><w:tblGrid><w:gridCol w:w="3000"/><w:gridCol w:w="3000"/></w:tblGrid><w:tr>
          <w:tc><w:tcPr><w:tcBorders><w:top w:val="double" w:sz="6" w:color="FF0000"/><w:left w:val="double" w:sz="6" w:color="000000"/></w:tcBorders></w:tcPr><w:p/></w:tc>
          <w:tc><w:tcPr><w:tcBorders><w:top w:val="double" w:sz="6"/><w:left w:val="double" w:sz="12"/></w:tcBorders></w:tcPr><w:p/></w:tc>
        </w:tr></w:tbl></w:body></w:document>"#;
        let document = layout_document(
            parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap(),
            Limits::default(),
            PART,
        )
        .unwrap();
        let borders = document
            .objects
            .iter()
            .filter(|o| o.stable_id.contains(":border:"))
            .collect::<Vec<_>>();
        assert_eq!(borders.len(), 4);
        for border in borders {
            let Visual::StrokeStyle { visual, .. } = &border.visual else {
                panic!("double border");
            };
            let Visual::PaintedShape {
                geometry: Geometry::Path { commands, .. },
                ..
            } = visual.as_ref()
            else {
                panic!("border path");
            };
            assert_eq!(
                commands.len(),
                2,
                "unequal colors or widths must not be merged"
            );
        }
    }

