    #[test]
    fn preserves_paragraph_before_spacing_in_docx_table_cells() {
        let xml = br#"<w:document xmlns:w="w"><w:body><w:tbl>
          <w:tblPr><w:tblBorders><w:top w:val="single" w:sz="2" w:color="123456"/><w:left w:val="single" w:sz="2" w:color="123456"/><w:bottom w:val="single" w:sz="2" w:color="123456"/><w:right w:val="single" w:sz="2" w:color="123456"/><w:insideH w:val="single" w:sz="2" w:color="123456"/><w:insideV w:val="single" w:sz="2" w:color="123456"/></w:tblBorders><w:tblCellMar><w:top w:w="0" w:type="dxa"/><w:left w:w="0" w:type="dxa"/><w:bottom w:w="0" w:type="dxa"/><w:right w:w="0" w:type="dxa"/></w:tblCellMar></w:tblPr>
          <w:tblGrid><w:gridCol w:w="6000"/></w:tblGrid>
          <w:tr><w:tc><w:p><w:pPr><w:spacing w:before="300" w:after="0"/></w:pPr><w:r><w:t>Spaced</w:t></w:r></w:p></w:tc></w:tr>
        </w:tbl><w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        let cell = document
            .objects
            .iter()
            .find(|object| object.kind == ObjectKind::Cell)
            .unwrap();
        let paragraph = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("Spaced"))
            .unwrap();

        let expected_before = 300.0 / TWIPS_PER_CSS_PIXEL;
        assert!((paragraph.bounds.y - cell.bounds.y - expected_before).abs() < 0.01);
        assert!(cell.bounds.height >= expected_before + paragraph.bounds.height);
        assert!(matches!(
            cell.visual,
            Visual::PaintedShape {
                stroke: Paint::Solid(0x1234_56ff),
                stroke_width,
                ..
            } if (stroke_width - 0.96).abs() < 0.01
        ));
    }

    #[test]
    fn renders_the_accepted_revision_view_and_field_results() {
        let xml = br#"<w:document xmlns:w="w"><w:body>
          <w:p>
            <w:del><w:r><w:t>deleted</w:t></w:r></w:del>
            <w:ins><w:r><w:t>accepted</w:t></w:r></w:ins>
            <w:r><w:fldChar w:fldCharType="begin"/><w:instrText> PAGE </w:instrText><w:fldChar w:fldCharType="separate"/><w:t>7</w:t><w:fldChar w:fldCharType="end"/></w:r>
          </w:p>
          <w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr>
        </w:body></w:document>"#;
        let parsed = parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap();
        let document = layout_document(parsed, Limits::default(), PART).unwrap();
        assert_eq!(document.objects[0].text.as_deref(), Some("accepted7"));
        assert!(
            document
                .diagnostics
                .iter()
                .any(|diagnostic| { diagnostic.message.contains("accepted revision view") })
        );
        assert!(!document.diagnostics.iter().any(|diagnostic| {
            diagnostic.message.contains("field instruction")
                && diagnostic.fidelity == crate::diagnostic::Fidelity::Unsupported
        }));
    }

