    #[test]
    fn resumes_full_width_after_a_floating_drawing_and_wraps_beside_a_floating_table() {
        let xml = br#"<w:document xmlns:w="w" xmlns:wp="wp"><w:body>
          <w:p><w:r><w:drawing><wp:anchor distL="0" distR="0"><wp:extent cx="1524000" cy="381000"/><wp:positionH relativeFrom="column"><wp:posOffset>1524000</wp:posOffset></wp:positionH><wp:positionV relativeFrom="paragraph"><wp:posOffset>0</wp:posOffset></wp:positionV><wp:wrapSquare/></wp:anchor></w:drawing><w:t>Text starts beside the image and continues at full width after the short image ends instead of staying in a narrow column.</w:t></w:r></w:p>
          <w:tbl><w:tblPr><w:tblpPr w:horzAnchor="margin" w:tblpXSpec="right" w:vertAnchor="text" w:tblpY="150" w:leftFromText="180"/><w:tblW w:w="0" w:type="auto"/></w:tblPr><w:tblGrid><w:gridCol w:w="2400"/></w:tblGrid><w:tr><w:trPr><w:trHeight w:val="900"/></w:trPr><w:tc><w:p><w:r><w:t>Floating table</w:t></w:r></w:p></w:tc></w:tr></w:tbl>
          <w:p><w:r><w:t>Following text stays beside the floating table.</w:t></w:r></w:p>
          <w:sectPr><w:pgSz w:w="6000" w:h="6000"/><w:pgMar w:top="600" w:right="600" w:bottom="600" w:left="600"/></w:sectPr>
        </w:body></w:document>"#;
        let document = layout_document(
            parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap(),
            Limits::default(),
            PART,
        )
        .unwrap();
        let drawing = document
            .objects
            .iter()
            .find(|object| object.stable_id.starts_with("docx:drawing:0:"))
            .unwrap();
        let wrapped = document
            .objects
            .iter()
            .filter(|object| object.stable_id.starts_with("docx:paragraph:0:fragment:"))
            .collect::<Vec<_>>();
        let table = document
            .objects
            .iter()
            .find(|object| object.kind == ObjectKind::Table)
            .unwrap();
        let following = document
            .objects
            .iter()
            .find(|object| {
                object.text.as_deref() == Some("Following text stays beside the floating table.")
            })
            .unwrap();

        assert_eq!(document.units.len(), 1);
        assert_eq!(wrapped.len(), 2);
        assert!(wrapped[0].bounds.width < wrapped[1].bounds.width);
        assert!(wrapped[1].bounds.y >= drawing.bounds.y + drawing.bounds.height);
        assert!(table.bounds.x >= document.units[0].width / 2.0);
        assert!(following.bounds.y < table.bounds.y + table.bounds.height);
        assert!(following.bounds.x + following.bounds.width <= table.bounds.x - 11.9);
    }

