    #[test]
    fn preserves_wps_connector_line_ends_and_vertical_flip() {
        let xml = br#"<w:document xmlns:w="w" xmlns:wp="wp" xmlns:a="a" xmlns:wps="wps"><w:body>
          <w:p><w:r><w:drawing><wp:inline><wp:extent cx="2149522" cy="1207827"/><wp:docPr id="1"/><a:graphic><a:graphicData><wps:wsp><wps:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="2149522" cy="1207827"/></a:xfrm><a:prstGeom prst="bentConnector3"><a:avLst/></a:prstGeom><a:ln><a:solidFill><a:srgbClr val="5B9BD5"/></a:solidFill><a:tailEnd type="triangle"/></a:ln></wps:spPr></wps:wsp></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>
          <w:p><w:r><w:drawing><wp:inline><wp:extent cx="2354239" cy="962167"/><wp:docPr id="2"/><a:graphic><a:graphicData><wps:wsp><wps:spPr><a:xfrm flipV="1"><a:off x="0" y="0"/><a:ext cx="2354239" cy="962167"/></a:xfrm><a:prstGeom prst="curvedConnector3"><a:avLst/></a:prstGeom><a:ln><a:solidFill><a:srgbClr val="5B9BD5"/></a:solidFill></a:ln></wps:spPr></wps:wsp></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>
          <w:sectPr/>
        </w:body></w:document>"#;
        let document = layout_document(
            parse_document_xml(xml, Limits::default(), PART, Vec::new()).unwrap(),
            Limits::default(),
            PART,
        )
        .unwrap();
        let drawings = document
            .objects
            .iter()
            .filter(|object| object.stable_id.starts_with("docx:drawing:"))
            .collect::<Vec<_>>();

        let Visual::PaintedShape {
            geometry: Geometry::Path { commands: bent, .. },
            ..
        } = &drawings[0].visual
        else {
            panic!("bent connector path expected");
        };
        assert!(
            bent.iter()
                .any(|command| matches!(command, PathCommand::ClosePath))
        );

        let Visual::PaintedShape {
            geometry: Geometry::Path {
                commands: curved, ..
            },
            ..
        } = &drawings[1].visual
        else {
            panic!("curved connector path expected");
        };
        let height = 962_167.0 / EMU_PER_CSS_PIXEL;
        assert!(
            matches!(curved.first(), Some(PathCommand::MoveTo { y, .. }) if (*y - height).abs() < 0.01)
        );
        assert!(
            matches!(curved.last(), Some(PathCommand::BezierCurveTo { y, .. }) if y.abs() < 0.01)
        );
    }

